INSERT INTO boundless.posts (id, user_id, space, topic, kind, lang, region, visa, title, body, price, deal, place, starts_on, ends_on, created_at) VALUES (900001, '00000000-0000-4000-9000-000000000021', 'global', 'food', 'recommend', 'en', 'seoul', 'd2', 'My first kimjang and my hands still smell like gochugaru', 'Our international club signed up volunteers to make kimchi with a neighborhood group for winter, and I ended up elbow-deep in cabbage for three hours. My back hurts and no amount of washing gets the gochugaru off my hands, but they sent me home with a whole tub of fresh kimchi so honestly, worth it. First kimjang ever and it lowkey felt like Dashain with way more chili. If you get the chance next season, just go, even if your Korean is as broken as mine 🙂', NULL, NULL, NULL, NULL, NULL, now() - interval '9965 minutes');
INSERT INTO boundless.posts (id, user_id, space, topic, kind, lang, region, visa, title, body, price, deal, place, starts_on, ends_on, created_at) VALUES (900002, '00000000-0000-4000-9000-000000000010', 'global', 'work', 'question', 'en', 'seoul', 'd10', 'Interview next week and it''s freezing — what do I wear?', 'I finally landed an interview for a marketing assistant role, my first since finishing my master''s, and of course it lands on the coldest week so far. Do I show up in a blazer and freeze on the subway, or wear my padded coat and arrive looking like a rice ball? 😅 Any tips for staying calm too — I keep rewriting my self-intro the night before. I''ll buy you a Pepero box if you help me decide!', NULL, NULL, NULL, NULL, NULL, now() - interval '9976 minutes');
INSERT INTO boundless.posts (id, user_id, space, topic, kind, lang, region, visa, title, body, price, deal, place, starts_on, ends_on, created_at) VALUES (900003, '00000000-0000-4000-9000-000000000007', 'global', 'market', 'buy', 'vi', 'seoul', 'd4', 'Áo khoác phồng 15k ở Đồng Miêu, lạnh đúng lúc 😭', 'Lạnh bất ngờ hôm qua mà tủ toàn áo mỏng, mình lết ra Đồng Miêu sớm luôn. Chốt được chiếc áo khoác phồng dày xinh giá 15.000₩, mặc ấm không khác hàng mới, quá hời 🥹. Trưa đi ngang Đường Đại học thấy lá phong vàng rụng đầy vỉa hè, đẹp muốn khóc luôn. Mua thêm hộp Pepero nhỏ, 11/11 tặng bạn cùng lớp tiếng cho vui. Chiều về bật chăn điện 30 phút rồi tắt cho đỡ hóa đơn gas, mn nhớ tiết kiệm nha!', 15000, 'reserved', 'Đồng Miêu', NULL, NULL, now() - interval '9961 minutes');
INSERT INTO boundless.posts (id, user_id, space, topic, kind, lang, region, visa, title, body, price, deal, place, starts_on, ends_on, created_at) VALUES (900004, '00000000-0000-4000-9000-000000000041', 'global', 'housing', 'question', 'en', 'gyeonggi', 'e7', 'First gas bill of the season nearly ended me', 'My one-room in Gyeonggi has an old-style boiler and the first cold snap hit it hard. The bill jumped to almost triple October, and I only ran the heating in the evenings. I bought an electric blanket and a door draft stopper as a defense budget. Anyone else in an older villa have real tricks, or is this just the November tax?', NULL, NULL, NULL, NULL, NULL, now() - interval '10013 minutes');
INSERT INTO boundless.posts (id, user_id, space, topic, kind, lang, region, visa, title, body, price, deal, place, starts_on, ends_on, created_at) VALUES (900005, '00000000-0000-4000-9000-000000000014', 'global', 'health', 'review', 'en', 'seoul', 'etc', 'Got my flu shot today — clinics are busy, go early', 'Finally got my flu shot at the small family clinic down the street from my academy this morning, and the nurse said they''ve been slammed since the temperature dropped, so go before 10am if you can. It was quick and cheaper than I feared, and my arm is only a little sore tonight. Friendly reminder for fellow teachers: with the big college exam on Thursday, some bus routes near test sites change, so leave extra early that morning. Stay warm, everyone — my fleece collection is finally earning its keep.', NULL, NULL, NULL, NULL, NULL, now() - interval '10040 minutes');
INSERT INTO boundless.posts (id, user_id, space, topic, kind, lang, region, visa, title, body, price, deal, place, starts_on, ends_on, created_at) VALUES (900006, '00000000-0000-4000-9000-000000000012', 'global', 'chat', 'chat', 'th', 'seoul', 'd4', 'โซลเริ่มหนาวจริงแล้ว!! สัปดาห์นี้เจออะไรบ้างคะ 🥶', 'สัปดาห์นี้โซลหนาวจริงจังแล้วค่ะ รีบไปซื้อแพดเดดโค้ตที่ดงแดมุนมาใส่ ตัวละ 30,000วอน ถูกจนตกใจ 🥶 วันพีโพโร 11/11 เพื่อนในตึกเรียนแบ่งกันกิน เลยได้ภูเขาช็อกโกแลตตั้งอยู่บนโต๊ะถึงตอนนี้ 🍫 วันสอบซึงนึงทั้งย่านเงียบแปลกๆ เพื่อนเกาหลีบอกให้เดินเบาๆ ก็อินไปกับเขาเต็มๆ ขอส่งกำลังใจให้เด็กที่สอบด้วยนะคะ ใครเป็นคนไทยเหมือนกันมีทริคกันหนาวยังไงมาแชร์หน่อยค่ะ กลัวค่าแก๊สเดือนนี้เกินตัว 555', NULL, NULL, NULL, NULL, NULL, now() - interval '10067 minutes');
INSERT INTO boundless.posts (id, user_id, space, topic, kind, lang, region, visa, title, body, price, deal, place, starts_on, ends_on, created_at) VALUES (900007, '00000000-0000-4000-9000-000000000033', 'global', 'food', 'question', 'km', 'chungbuk', 'f6', 'សៅរ៍នេះធ្វើគីមជាំងនៅផ្ទះម៉ាក់មាម 😳🌶️❤️', 'សប្ដាហ៍នេះចិត្តអូនរីករាយណាស់ ព្រោះសៅរ៍នេះត្រូវទៅធ្វើគីមជាំងនៅផ្ទះម៉ាក់មាមប្ដី ❤️ គ្រប់ឆ្នាំអូនគ្រាន់តែជួយលាងសណ្ដែកបាយឆ្អែងនិងលាបទឹកប្រហុតក្រឡូក តែឆ្នាំនេះចង់សាកលាយក្រឡុកនិងប្រហុតខ្មែរបន្តិចទៅក្នុងបាយឆ្អែងគីមជាំងទៀត 🌶️ ខ្លាចមេគ្រួសារចាស់ៗញ៉ាំងភ្ញាក់ ព្រោះក្លិនប្រហុតខ្លាំងណាស់ បុគ្គលកូរេមិនដែលបានក្រអឺតទេ។ ប្ដីថាមិនអីទេ តែឃើញម៉ាក់មាមញញឹមរក្សាសីលរកសិន អូនក៏ពិបាកចិត្តដែរ 🙈 បងប្អូននៅពហុវប្បធម៌ប្រាប់ថាឲ្យលាយចានតូចមួយដាច់ដោយឡែកសាកជាមុនសិន ដើម្បីកុំឲ្យប៉ះពាល់គីមជាំងរបស់គ្រួសារ។ មិត្តភក្តិធ្លាប់ប្រើម្រ៉េចស្ទីលខ្មែរចូលក្នុងគីមជាំងអត់? សូមបងប្អូនជួយផ្តល់ដំបូន្មានបន្តិច ដើម្បីកុំឲ្យអូនអាម៉ាស់ចំពោះមុខមេគ្រួសារចាស់ៗ 🙏❤️', NULL, NULL, NULL, NULL, NULL, now() - interval '9216 minutes');
INSERT INTO boundless.posts (id, user_id, space, topic, kind, lang, region, visa, title, body, price, deal, place, starts_on, ends_on, created_at) VALUES (900008, '00000000-0000-4000-9000-000000000030', 'global', 'chat', 'chat', 'mn', 'incheon', 'e9', 'Бямба гарагт анхны кимжангаа хийнэ', 'Ажлын охиноосоо урилга аваад бямба гарагт ажлын хамт кимжан хийхээр боллоо. Резинэн бээлий, өвдөгний дэвсгэр, угаахаар чөлөөтэй хувцасаа бэлдээд байна. Гарагийн өглөө эрт ARC, NHIS картаа авч очиж ханиадны вакцин хийлгэхээр төлөвлөж байна. Өрөөний цонх нимгэн тул орой нь бөмбөлөг хальс наана, дулаан хадгалах гэж. Бүгд дулаан өнгөрүүлээрэй.', NULL, NULL, NULL, NULL, NULL, now() - interval '8827 minutes');
INSERT INTO boundless.posts (id, user_id, space, topic, kind, lang, region, visa, title, body, price, deal, place, starts_on, ends_on, created_at) VALUES (900009, '00000000-0000-4000-9000-000000000016', 'global', 'chat', 'chat', 'ko', 'seoul', 'f5', '배포 주간이 페페로 데이랑 겹치네요', '11월 11일에 우리 팀 업데이트가 정식 배포됩니다. 사전에 크런치가 좀 돌다가 겨우 이번 주에 정리돼서 이제야 숨을 돌리는 중입니다. 출시 주간에 수능 같은 이벤트가 겹치면 커뮤니티 반응이 삭고, QA 버그 제보 처리가 밀리는 걸 감안하면 다행히 이번엔 일정이 잘 걸렸습니다.
INSERT INTO boundless.posts (id, user_id, space, topic, kind, lang, region, visa, title, body, price, deal, place, starts_on, ends_on, created_at) VALUES (900010, '00000000-0000-4000-9000-000000000044', 'global', 'chat', 'chat', 'en', 'seoul', 'e7', 'Cold snap = lamination season at last 🥐', 'Pepero Day almost finished me — chocolate éclairs gone by 2pm and we were piping till midnight. But this cold snap is a gift: the butter finally behaves and the croissants came out with perfect layers this morning. Voilà! One day off soon to catch the last autumn leaves and wander the Christmas pop-ups in Seongsu for dessert inspiration 🍂', NULL, NULL, NULL, NULL, NULL, now() - interval '8637 minutes');
INSERT INTO boundless.posts (id, user_id, space, topic, kind, lang, region, visa, title, body, price, deal, place, starts_on, ends_on, created_at) VALUES (900011, '00000000-0000-4000-9000-000000000025', 'global', 'chat', 'chat', 'en', 'busan', 'e9', 'Cold week at the port, flatfish run about to start', 'First real cold snap hit Busan and my ondol room is weak as always, but I got an electric blanket at the market stall for under 30,000 won, no problem, 30 minutes on a timer before bed and the gas stays off. Winter flatfish run starts this week so work gets busy from now. Kimjang season is good to me, the older ajummas at the port gave me extra cabbage kimchi again so dinner is covered. 👍', NULL, NULL, NULL, NULL, NULL, now() - interval '7802 minutes');
INSERT INTO boundless.posts (id, user_id, space, topic, kind, lang, region, visa, title, body, price, deal, place, starts_on, ends_on, created_at) VALUES (900012, '00000000-0000-4000-9000-000000000037', 'global', 'trip', 'question', 'ko', 'busan', 'f6', '금정산 단풍, 이번 주말이 마지막일 것 같아요', '첫 한파가 오니 아침마다 난방비 걱정이 먼저 나오네요 ㅎㅎ 저희 집은 오래된 아파트라 열이 금방 새서 창문에 뽁뽁이와 문풍지를 미리 붙여놨습니다. 그래도 이번 주말은 조금 설레요. 토요일엔 시어머니와 두 번째 김장을 하고, 일요일 아침엔 바람이 단풍을 다 떨어뜨리기 전에 금정산에 다녀올까 합니다. 혹시 요즘 금정산이나 케이블카 주변 단풍 상태 보신 분 계시면 알려주세요. 봄 진달래만큼 단축이라 미리미리 가야 한다는 걸 부산 살면서 7년 동안 배웠거든요 아이가. 다들 감기 조심하시고, 목요일 수험생 여러분도 좋은 결과 있으시길 응원합니다.', NULL, NULL, NULL, NULL, NULL, now() - interval '7767 minutes');
INSERT INTO boundless.posts (id, user_id, space, topic, kind, lang, region, visa, title, body, price, deal, place, starts_on, ends_on, created_at) VALUES (900013, '00000000-0000-4000-9000-000000000022', 'global', 'chat', 'worry', 'ne', 'chungnam', 'e9', 'पहिलो चिसो: ग्रीनहाउसको हिटर र ग्यास बिलको चिन्ता', 'यो हप्तादेखि बिहान ५ बजै उठेर पहिले हिटर जाँच गर्न जान्छु। ग्रीनहाउसमा भित्रपट्टि अर्को पातलो बिनल तन्काउँदा हावाको तह बन्छ, साँझको चिसोले गोभी-नापी कम थिच्छ। तर रातभर हिटर चलाउँदा ग्यास बिल कति बढ्ला भन्ने सोच्दा चिन्ता लाग्छ। मालिक्नीले किम्जाङ सिकाउनुभयो र दुई डल्लो किम्ची घर पठाउनुभयो, खाना खाँदा मन तात्यो। अर्को हप्ता गुन बोगनसोमा फ्लू सुई लगाउँछु। चुङनामका फार्मका साथीहरू, रातमा हिटर ओहोर्याउने सस्तो तरिका भए बताउनुहोस्।', NULL, NULL, NULL, NULL, NULL, now() - interval '7424 minutes');
INSERT INTO boundless.posts (id, user_id, space, topic, kind, lang, region, visa, title, body, price, deal, place, starts_on, ends_on, created_at) VALUES (900014, '00000000-0000-4000-9000-000000000024', 'global', 'food', 'question', 'id', 'seoul', 'd2', 'Cari makanan halal sekitar Seongsu, ada info? 🎄✨', 'Gais, finals makin deket tapi gue masih pengen banget ngejar Christmas pop-up di Seongsu minggu ini, sebelum lab dan laporan menelan gue utuh 😭 Sekalian gue pengen nambahin peta halal gue — ada yang pernah makan halal-friendly di sekitar situ? Masakan Asia Selatan, kebab, ayam halal, atau warung kecil apapun cerita ke gue ya! Peta gue di Seongsu masih kosong banget, tiap kali ditanya temen baru gue cuma bisa nunjuk arah seberang sungai 🥲
INSERT INTO boundless.posts (id, user_id, space, topic, kind, lang, region, visa, title, body, price, deal, place, starts_on, ends_on, created_at) VALUES (900015, '00000000-0000-4000-9000-000000000041', 'global', 'housing', 'info', 'en', 'gyeonggi', 'e7', 'Cold snap patch notes: heating + suneung commute', 'First cold snap hit my poorly insulated one-room in Gyeonggi hard, so here are this week''s patch notes.
INSERT INTO boundless.posts (id, user_id, space, topic, kind, lang, region, visa, title, body, price, deal, place, starts_on, ends_on, created_at) VALUES (900016, '00000000-0000-4000-9000-000000000029', 'global', 'health', 'question', 'mn', 'seoul', 'd2', 'Дадлагаас өмнө ханиаднаас сэргийлж байна', 'Энэ сарын сүүлээр 병원 дээр дадлага эхлэх болохоор эхний хүйтэнд ханиад хүрэхээс айж байна 😷 Тиймээс өөртөө энгийн дүрэм гаргасан: метро дээр маск зүүх, гэртээ ормогц гараа 20 секунд угаах, өрөөндөө хувин ус тавьчихсан — хамрын салст бүрхэвч хатахгүй байх нь биед зөв хамгаалалт гэдгийг сургуульд л сурсан. Унтахын өмнө цахилгаан хөнжлөө 30 минутын таймер дээр асаагаад орхидог болсоор шөнөжин бойлер асаахгүй байгаа ч сайхан унтаж байна. 11/11-нд ангийнхантай Pepero солилцсон нь хүйтэн өдрийг ч гэсэн халуун болгосон 😊 Та нарын өвлийн эхний сард биеэ хамгаалах жижиг дүрэм байдаг уу? Хуваалцаач, надад бас хэрэгтэй байна.', NULL, NULL, NULL, NULL, NULL, now() - interval '6598 minutes');
INSERT INTO boundless.posts (id, user_id, space, topic, kind, lang, region, visa, title, body, price, deal, place, starts_on, ends_on, created_at) VALUES (900017, '00000000-0000-4000-9000-000000000003', 'global', 'chat', 'question', 'zh', 'seoul', 'e7', 'Pepero Day 劫后余生，周四还有更大的挑战', '哈哈先说快乐的部分：11/11 我们办公室彻底被 Pepero 淹没了，前台堆起一整面巧克力墙，客户来开会人手一盒，连来送样品的快递小哥都被塞了两根 🍫 我做营销的，一边吃一边由衷佩服这个把饼干卖成全民节日的操作，已经默默记进今年的 campaign 案例库了。限定口味甜到上头，快乐是真的，热量也是真的。
INSERT INTO boundless.posts (id, user_id, space, topic, kind, lang, region, visa, title, body, price, deal, place, starts_on, ends_on, created_at) VALUES (900018, '00000000-0000-4000-9000-000000000008', 'global', 'food', 'home', 'ko', 'jeonnam', 'f6', '김장 전에 굵은 소금 계산 공유해요 (배추 열 포기)', '내일 시어머니랑 김장이라 오늘 저녁부터 배추 소금 절임을 준비해요. 경험으로는 배추 열 포기(약 25kg)에 굵은 소금 2.5kg, 열 퍼센트 정도면 충분했어요. 굵은 소금은 두꺼운 줄기 사이에 꼼꼼히 뿌리고 여섯 시간쯤 뒤에 한 번 되집어요. 갓은 열 포기만 덜어서 항아리에 베트남식 절인 갓을 담가둘 거예요. 밤마다 비닐하우스 보온 부직포 씌우는 게 요즘 제일 힘드네요. (궁금해서 그런데 ''염도''가 무슨 뜻이에요?) 다들 김장 잘하시고 감기 조심하세요 🙏', NULL, NULL, NULL, NULL, NULL, now() - interval '6336 minutes');
INSERT INTO boundless.posts (id, user_id, space, topic, kind, lang, region, visa, title, body, price, deal, place, starts_on, ends_on, created_at) VALUES (900019, '00000000-0000-4000-9000-000000000006', 'global', 'chat', 'chat', 'vi', 'gyeonggi', 'e9', 'Chốt Pepero cho cả line, kèo 11/11 vừa rẻ vừa vui', 'Dịp 11/11 mình chốt luôn mấy hộp Pepero ở cửa hàng tiện lợi gần nhà máy, đang có kèo mua 2 tặng 1 nên rẻ hơn mua lẻ gần nửa, ban ca đêm được chia quà ai cũng vui hẳn. Còn chuyện buồn là hoá đơn gas tháng này nhìn mà tay run, may nhờ kèo 외출 mode với chăn điện bật 30 phút rồi tắt mà con số đỡ hơn mình sợ nhiều, tuần này ráng giữ ấm bằng chăn bự thôi. Tối thứ 7 mình đi kimjang ở trung tâm đa văn hoá gần đây, ai ở Hwaseong muốn đi cùng thì hô một tiếng, mang găng tay đúng cỡ với đồ dính ớt thoải mái là chốt nha!', NULL, NULL, NULL, NULL, NULL, now() - interval '5861 minutes');
INSERT INTO boundless.posts (id, user_id, space, topic, kind, lang, region, visa, title, body, price, deal, place, starts_on, ends_on, created_at) VALUES (900020, '00000000-0000-4000-9000-000000000021', 'global', 'chat', 'chat', 'en', 'seoul', 'd2', 'First kimjang this Saturday — wish me luck', 'The international ambassadors program finally got me a volunteer slot at a neighborhood kimjang this weekend and it''s my first ever, no joke. I''ve been collecting tips from this app like it''s exam season: rubber gloves in my actual size, clothes I can throw straight in the wash, and a knee pad because my back will definitely file a complaint 😂 Honestly the scary part is just being the slowest one next to the ajummas, but everyone here says nobody grades you, they just fix your hands and keep you moving. I''m also bringing a box of Pepero for the volunteers because 11/11 is basically a national holiday for someone with my sweet tooth 🍫 Now if my gas bill survives the heater being off all Saturday, it''ll be a perfect week 😤❄️', NULL, NULL, NULL, NULL, NULL, now() - interval '5131 minutes');
INSERT INTO boundless.posts (id, user_id, space, topic, kind, lang, region, visa, title, body, price, deal, place, starts_on, ends_on, created_at) VALUES (900021, '00000000-0000-4000-9000-000000000019', 'global', 'chat', 'chat', 'ko', 'incheon', 'f4', '일요일에 처음으로 아파트 공동김장에 나갑니다', '입주민 공동김장 모집 공고를 보고 저도 처음으로 신청했어요. 사실 우리 집 물들이통은 아직 비어 있어서, 올해는 동네 어르신들한테 절임배추 절이는 손놀림부터 배워오려고 합니다. 고무장갑 안에 얇은 면장갑을 한 벌 더 끼우고, 무릎패드랑 갈아입을 상의까지 챙겼어요. 지난주 첫 한파 덕에 보일러는 외출 모드, 전기요는 30분 타이머로 돌리고 있는데 이 덕에 가스요금 겁은 조금 덜었어요. 페페로데이에는 창고 팀원들한테 한 박스씩 나눠줬는데 사기가 확 올랐답니다. 목요일 수능 아침 배송 일정도 전부 10시 이후로 미뤄놨고요. 일요일에 무사히 다녀와서 김치 몇 통 인증으로 다시 찾아올게요 ^^', NULL, NULL, NULL, NULL, NULL, now() - interval '5039 minutes');
INSERT INTO boundless.posts (id, user_id, space, topic, kind, lang, region, visa, title, body, price, deal, place, starts_on, ends_on, created_at) VALUES (900022, '00000000-0000-4000-9000-000000000023', 'global', 'chat', 'chat', 'id', 'gyeongnam', 'e9', 'Kimjang pertama selesai, tangan masih bau gochugaru', 'Sabtu kemarin akhirnya kimjang pertama saya bareng kelas Korea di sini, ditugaskan membaluri kol daun demi daun selama tiga jam. Ternyata membaluri kol lebih melelahkan daripada shift las malam, pinggang rasanya seperti habis mengangkat blok kapal 😄 Sarung tangan karet ukuran sendiri dan pelindung lutut yang disarankan teman-teman di sini benar-benar menyelamatkan, terima kasih sarannya minggu lalu. Ibu-ibu lokal langsung membetulkan posisi tangan kalau salah, tidak ada yang dinilai, santai saja katanya, dan memang benar. Kimchi dibawa pulang satu tong besar, disuruh ditinggal satu hari di suhu ruang baru masuk kulkas, malam ini sudah masuk menu makan malam dorm. Yang belum pernah ikut, tahun depan gaskeun, tidak usah takut bahasa Korea saya juga cuma setengah paham.', NULL, NULL, NULL, NULL, NULL, now() - interval '4353 minutes');
INSERT INTO boundless.posts (id, user_id, space, topic, kind, lang, region, visa, title, body, price, deal, place, starts_on, ends_on, created_at) VALUES (900023, '00000000-0000-4000-9000-000000000032', 'global', 'chat', 'chat', 'km', 'gyeonggi', 'e9', 'សប្ដាហ៍ត្រជាក់ដំបូង និងគីមជាំងលើកដំបូងរបស់ខ្ញុំ', 'កម្ដៅក្នុងផ្ទះស្មៅព្រំរបស់យើងចាស់ណាស់ ដូច្នេះវិក្កយបត្រហ្គាសចុងខែធ្វើឲ្យខ្ញុំបារម្ភ ខ្ញុំក៏បិទវាពេលចេញធ្វើការ ហើយពាក់សម្លៀកបំពាក់ជាន់ច្រើនស្រទាប់ជំនួសវិញ។ សប្ដាហ៍នេះក៏មានរឿងរីករាយពីរដែរ ថ្ងៃទី ១១ កូនស្រីរបស់ចៅហ្វាយបានផ្ដល់ប្រអប់ប៉េប៉េរូមួយមកខ្ញុំ ហើយថ្ងៃអាទិត្យគ្រួសារចៅហ្វាយអញ្ជើញខ្ញុំទៅធ្វើគីមជាំងជាលើកដំបូង។ ខ្ញុំរៀបចំស្រោមដៃកៅស៊ូសមនឹងដៃ និងខ្នើយជង្គង់រួចហើយ បើបងប្អូនណាមានគន្លឹះថែមទៀត សូមប្រាប់ខ្ញុំផង 🙏❄️', NULL, NULL, NULL, NULL, NULL, now() - interval '3564 minutes');
INSERT INTO boundless.posts (id, user_id, space, topic, kind, lang, region, visa, title, body, price, deal, place, starts_on, ends_on, created_at) VALUES (900024, '00000000-0000-4000-9000-000000000038', 'global', 'chat', 'chat', 'ja', 'seoul', 'd4', 'ペペロデーの箱交換と初めての패딩', '11月11日、語学堂のクラスでみんなでペペロの箱を交換しました。机の上にチョコがいくつも並んで、休み時間の教室が小さなパーティーみたいでした。寒波が来てからは初めての패딩を買って、朝の通学が少し楽になりました。夜はガス代が気になるので、窓にプチプチを貼って、電気毛布は寝る30分前だけつけています。木曜日は수능ですね。夜遅く机に向かう学生さんの姿を見ると、自分の受験時代を思い出してそっと応援したくなります。みなさんもどうぞ温かくしてお過ごしください ❄️', NULL, NULL, NULL, NULL, NULL, now() - interval '3319 minutes');
INSERT INTO boundless.posts (id, user_id, space, topic, kind, lang, region, visa, title, body, price, deal, place, starts_on, ends_on, created_at) VALUES (900025, '00000000-0000-4000-9000-000000000004', 'global', 'chat', 'chat', 'ko', 'incheon', 'f6', '김장은 끝났고, 이제 12월 난방비를 대비하실 때예요', '시어머니와 김장을 마치고 냉동실이 김치통으로 가득해졌어요. 양념은 전날 미리 만들어 두고 절인 배추는 물기를 꼼꼼히 빼 두니 당일 작업이 한결 수월했어요. 페페로데이에는 아이 반 몫을 사 두고도 부족해서 결국 두 박스를 더 사러 갔네요 ㅎㅎ
INSERT INTO boundless.posts (id, user_id, space, topic, kind, lang, region, visa, title, body, price, deal, place, starts_on, ends_on, created_at) VALUES (900026, '00000000-0000-4000-9000-000000000028', 'global', 'chat', 'funny', 'en', 'jeju', 'etc', 'Kimjang with the kitchen crew tomorrow, wish my back luck', 'Tomorrow our kitchen crew does kimjang with the ajummas from the neighborhood market and I''m the supply manager because of course I am 😂 Rubber gloves in everyone''s actual size are somehow my problem now, hays. I saved the salt ratio posted here like I save visa screenshots — 2.5kg coarse salt per 10 heads, flip after six hours — and our sous chef says that''s exactly what her mom does 🥶 I''m also packing extra kimbap because kimjang day always turns into a whole potluck and nobody ever thinks about lunch. Salamat to whoever explained 염도, the kitchen noonas say finished kimchi should land around 1.5 to 2 percent. Pray for my back, it''s still recovering from year-end party overtime starting way too early 🍂', NULL, NULL, NULL, NULL, NULL, now() - interval '1875 minutes');
INSERT INTO boundless.posts (id, user_id, space, topic, kind, lang, region, visa, title, body, price, deal, place, starts_on, ends_on, created_at) VALUES (900027, '00000000-0000-4000-9000-000000000025', 'global', 'market', 'buy', 'en', 'busan', 'e9', 'New to the docks? Cheap rubber boots and thermals', 'First cold week and the new guys at the port keep asking, so here it is. Rubber boots are cheapest at the market stalls near Bujeon, thick ones under 20,000 won, try them on with your work socks before you pay, and thermal layers are the same price range, no problem. Fresh mackerel at the dawn stalls by the port drops in price after the boats come in around 6am, don''t pay the first price you hear. 👍', 20000, 'done', 'Bujeon', NULL, NULL, now() - interval '1649 minutes');
INSERT INTO boundless.posts (id, user_id, space, topic, kind, lang, region, visa, title, body, price, deal, place, starts_on, ends_on, created_at) VALUES (900028, '00000000-0000-4000-9000-000000000041', 'global', 'chat', 'chat', 'en', 'gyeonggi', 'e7', 'Kimjang field report: back survived, hands didn''t', 'Patch notes from my first kimjang with the team on Saturday.
INSERT INTO boundless.posts (id, user_id, space, topic, kind, lang, region, visa, title, body, price, deal, place, starts_on, ends_on, created_at) VALUES (900029, '00000000-0000-4000-9000-000000000013', 'global', 'chat', 'worry', 'en', 'busan', 'e7', 'First kimjang with my coworkers tomorrow — wish me luck', 'Sis, after weeks of hearing about it, tomorrow is finally my first kimjang with my Korean coworkers at my manager''s family home and I am so nervous lol 😅 I keep picturing an ajumma grabbing my hands mid-chop to fix them, which honestly might be the best thing that could happen.
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900001, 900004, '00000000-0000-4000-9000-000000000044', 1, 'Same at our bakery — the first week of the cold snap sent our gas bill way up, and that''s before year-end pre-orders even peak. For the one-room, thick curtains over the windows and keeping doors closed to heat only one room made a bigger difference for me than anything else. And yes, electric blankets are worth every won — ours lives in the break room now 🥐', now() - interval '9936 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900002, 900002, '00000000-0000-4000-9000-000000000034', 1, 'Поздравляю, это же маркетинг — моя мечта, держу кулачки!!! 💪 Мой проверенный способ: едешь в пуховике, а пиджак/блузку в пакете или папке и переодеваешься в туалете метро перед офисом — все так делают, норм 😄 Самопрезентацию сведи к трём ключевым пунктам и повтори их по дороге, плюс приди на 20 минут раньше — спокойствие само придёт. Хваитинг! А Pepero оставь себе, удачи хватит 😊', now() - interval '9908 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900003, 900001, '00000000-0000-4000-9000-000000000043', 1, 'Trop bien, franchement ça me motive encore plus !! 😆 Moi je fais mon premier kimjang dimanche avec mon buddy program, 김장 화이팅 !! Tu avais des gants fournis ou on trempe les mains direct dans le gochugaru ? Et le tub de kimchi, tu l''as mis tout de suite au frigo ou tu leisses dehors un peu ? Merci les amis 🙏', now() - interval '9930 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900004, 900001, '00000000-0000-4000-9000-000000000002', 2, '첫 김장 잘 마치셨네요 👍 고춧가루 냄새는 식용유로 손을 비빈 다음 주방세제로 씻으면 잘 빠지고, 우유로 닦아도 됩니다. 다음엔 고무장갑 꼭 끼고, 무릎패드 하나 챙기면 허리가 훨씬 편해요. 마, 김치는 사흘쯤 지나야 제맛이니 조금만 기다려 보세요.', now() - interval '9937 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900005, 900004, '00000000-0000-4000-9000-000000000012', 2, 'ค่าแก๊สเดือนนี้ฉันก็ลุ้นแทบแย่เหมือนกันค่ะ ฮีตเพิ่งเปิดครั้งแรกแล้วมือสั่นเลย 🥶 เคล็ดลับจากห้องเดียวของฉันคืออย่าปิดบอยเลอร์ทิ้งทั้งวัน ตั้งโหมดเวชุลเฉยๆ ไว้จะประหยัดกว่าปิดแล้วเปิดใหม่ค่ะ แล้วเอาผ้าห่มเก่าม้วนๆ ดันใต้ประตูกันลมเฉียด อุ่นขึ้นเดแบคเลย ส่วนผ้าห่มไฟฟ้าเปิด 30 นาทีก่อนนอนแล้วปิดก็พออุ่นถึงเช้า 555 ถือซะว่าเป็นภาษีพฤศจิกายของคนอยู่เกาหลีละกันนะ สู้ๆ 🍫', now() - interval '9943 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900006, 900004, '00000000-0000-4000-9000-000000000025', 3, 'Same here boss, my ondol room is weak and the bill already jumped this week. Old trick from the port guys: bubble wrap on the window glass and a rolled towel pushed under the door, costs almost nothing and the room holds heat way better. I am also hunting a cheap electric blanket, the big market stalls usually sell them under 30,000 won, no problem finding one there. 👍', now() - interval '9608 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900007, 900001, '00000000-0000-4000-9000-000000000022', 3, 'मैले पनि यो हप्ता मालिक्नीसँगै किम्जाङ गरेँ र दुई डल्लो किम्ची घर ल्याएँ। गोचुगारुले हात जलाउँछ, त्यसैले लामो रबरको ग्लाभ्स (고무장갑) लगाउनुहोस्, नत्र रातभर पोल्छ। मालिक्नीले फ्रिजमा हाल्नुअघि एक दिन कोठाको तापमा राख्दा मीठो हुन्छ भन्नुभयो, मैले त्यसै गरेँ।', now() - interval '9718 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900008, 900004, '00000000-0000-4000-9000-000000000023', 4, 'Di dorm kami di Okpo juga ondol nyala semaleman begitu gelombang dingin pertama datang, tagihan gas naik hampir dua kali lipat 😄 Yang paling ngefek di tempat saya: setel boiler ke mode 외출 tiap keluar shift, panaskan satu kamar aja dengan pintu ditutup, dan selimut listrik dinyalakan 30 menit sebelum tidur lalu dimatikan lagi. Sumbat celah bawah pintu pakai handuk tua digulung, gratis dan ampuh. Santai, yang begini biasanya cuma dua-tiga bulan, habis itu tagihan turun lagi.', now() - interval '9639 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900009, 900005, '00000000-0000-4000-9000-000000000030', 1, 'Баярлалаа, яг цагтаа орлоо. Би бямба гарагаас өмнө ханиадны вакцин хийлгэх гэсэн ч дүүргийн эмнэлэгүүд гадаадын иргэдийг урьдчилан цаг авалгүй хүлээж авдаг уу гэдгийг мэдэхгүй байна. Таны эмнэлэг ARC-аас өөр баримт шаардсан уу?', now() - interval '9615 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900010, 900001, '00000000-0000-4000-9000-000000000030', 4, 'Би ч бас энэ бямба ажлын охиноосоо урилга аваад анхны кимжангаа хийх гэж байна. Доорх зөвлөгөөг уншаад резинэн бээлий, өвдөгний дэвсгэрээ авч явахаар боллоо. Хийсний дараа хэрхэн байснаа бичиж тавио.', now() - interval '9642 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900011, 900004, '00000000-0000-4000-9000-000000000020', 5, 'यस्तै भयो यार, हाम्रो डोर्ममा पनि पहिलो ग्याँस बिल अक्टोबरभन्दा झन्डै दोब्बर आयो। मैले गरेको कुरा: झ्यालमा बाक्लो पर्दा, ढोकामुनि पुरानो कम्बलको draft stopper, र बोइलर बिहान-बेलुका मात्र २० डिग्रीमा सेट गरेर सुत्नुअघि बन्द गरी electric blanket चलाउने। यो हप्ता त्यसैले बिल धेरै बढेन। पुरानो भिल्लामा एउटा कोठा मात्र तताउनुले ठूलो फरक पार्छ।', now() - interval '9652 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900012, 900005, '00000000-0000-4000-9000-000000000020', 2, 'म पनि यसै हप्ता गिमहेको बोगन्सोमा फ्लू सुई लगाएँ, बिहानै गएकोले लाइन छोटो थियो — २० मिनेटमा सकियो, हात एक रात मात्र दुख्यो। आरसी र स्वास्थ्य बिमा कार्ड लिएर जानुहोला। लाइनका साथीहरूलाई अझै फुकाइरहेको छु, एउटाको खोकीले पूरा सेक्सन अल्मलिन्छ यार।', now() - interval '9610 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900013, 900004, '00000000-0000-4000-9000-000000000016', 6, '옛 보일러 빌라 경험으로 말하면, 매번 끄고 켜는 것보다 외출 모드를 유지하고 앱으로 오전·저녁 예약난방 1시간씩만 돌리는 게 결과적으로 더 쌌습니다. 문 아래 수건, 창문 단열필름(에어캡)이 제일 가성비 좋고, 전기요는 취침 30분 전에 켜고 잘 때는 끄세요. 11월 난방비는 매년 보스전이지만 12월 중반쯤 너프되니 그때까지만 버티면 됩니다.', now() - interval '9532 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900014, 900004, '00000000-0000-4000-9000-000000000041', 0, 'Same situation here — one-room in Gyeonggi, old boiler, bill nearly tripled after the first cold snap. Three things that actually cut my bill last winter: 1) switch the boiler to 외출 (out) mode whenever you leave — reheating a cold room is cheaper than holding it warm all day, 2) bubble wrap or the cheap window film from Daiso on the glass, plus a rolled towel under the door, 3) set heating to 20°C with 예약 (timer) instead of running it all night, and let the electric blanket do the last 30 minutes before bed, then off. The November tax is real, but those three cut my December bill by roughly a third.', now() - interval '9573 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900015, 900001, '00000000-0000-4000-9000-000000000045', 5, 'Okay this is exactly the nudge I needed — my co-teacher invited me to kimjang with her family this Saturday and I''ve been quietly terrified of chopping the baechu wrong in front of her halmoni, eh 😅 Did they walk you through the salting step by step, or do you just get thrown in elbow-deep? Taking notes on the rubber gloves and knee pad for sure. 🍁', now() - interval '9573 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900016, 900001, '00000000-0000-4000-9000-000000000039', 6, '저도 이번에 한국 직원들과 처음 김장을 해 봤는데, 아직도 그 얘기만 하고 있어요 😄 고무장갑은 꼭 끼고 가세요, 저는 초반에 장갑 없이 하다가 밤에 손이 얼얼했어요. 김치는 냉장고에 바로 넣기보다 서늘한 곳에서 하루 정도 익혀야 제맛이더라고요. 썰고 버무리다 보면 어색함도 금방 풀리니까 첫 김장 너무 재밌었죠, 대박 경험이었어요!', now() - interval '9522 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900017, 900005, '00000000-0000-4000-9000-000000000039', 3, '덕분에 버스 노선 정보 미리 알아가요, 감사해요! 저도 목요일 수능 날에 고객 물품 배송이 예정돼 있어서 아침 도로 통제가 걱정이었는데, 시험장 근처는 오전 7시쯤부터 통제되니 택배 기사님께 낮 시간대로 바꿔 달라고 미리 부탁하려고요. 접수는 10시 전에 하라는 팁도 수첩에 메모했어요 📝', now() - interval '9491 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900018, 900004, '00000000-0000-4000-9000-000000000019', 7, '저도 오피스텔이라 이번 첫 한파에 가스요금 보고 깜짝 놀랐어요. 제일 효과를 본 건 외출 모드로 놓고 방 하나만 문 닫고 데우는 것, 창문에 뽁뽁이 붙이기, 문 밑에 젖은 수건 말아 끼우기였어요. 전기요는 타이머 달린 걸로 시장에서 3만 원 안쪽으로 사서 자기 30분 전에 켰다가 끄니까 보일러를 아예 끄고 잘 수 있어서 오히려 더 아꼈어요. 11월엔 다들 원래 이렇게 고생하니 너무 조급해하지 않으셔도 돼요.', now() - interval '9571 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900019, 900004, '00000000-0000-4000-9000-000000000001', 8, '我是今年刚买的电热毯，确实值。实操经验：出门把锅炉调成외출(外出)模式，比整天保温省得多；窗户贴气泡膜、门缝塞旧毛巾，成本几乎为零。电热毯睡前定时开30分钟就够，整夜开又费电又干。11月账单高是正常的，照这个方法12月能明显降下来。', now() - interval '9377 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900020, 900004, '00000000-0000-4000-9000-000000000018', 9, 'Ой, знакомая боль — у меня тоже однушка со старым бойлером, и ноябрьский газ это отдельный вид ужаса 😅 Мой способ: нампхан ставлю на 20° с ночным таймером (ечхак), а за 30 минут до сна включаю электрическое одеяло с таймером — оно само выключается, и газ почти не тратим. Сама сейчас охочусь за таким одеялом, на больших рынках видела до 30 тысяч вон! Ещё полотенце в рулоне под дверь и пупырку на окно — копейки, а тепло держат лучше пуха. Чидаймиз, дружище, эту ноябрьскую подать переживём, обнимаю 🧡', now() - interval '9365 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900021, 900005, '00000000-0000-4000-9000-000000000024', 4, 'Thanks reminder-nya gais!! 😭🙏 Gue juga nunda terus vaksin flu, besok pagi banget mau ke klinik kampus deh sebelum pada ngantre pas pekan suneung. Gue siapin ARC sama kartu NHIS doang sih, tapi ada yang pernah ke klinik kampus, perlu reservasi dulu nggak ya? Semoga lengannya nggak sakit lama, Pepero Day kan bentar lagi, gue butuh tangan dua-duanya buat pegang kotaknya 😂', now() - interval '9440 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900022, 900004, '00000000-0000-4000-9000-000000000037', 10, '아이가, 저도 요즘 고지서 생각만 하면 한숨이 먼저 나와요 ㅎㅎ 저희 집도 오래된 빌라라 단열이 안 좋은데, 경험상 보일러를 외출 모드로 두고 방문을 닫아 한 방만 데우는 게 제일 효과가 컸어요. 창문에 뽁뽁이와 문풍지를 붙이고 두꺼운 커튼을 치는 것도 은근히 큰 도움이 되고요. 전기요는 취침 30분 전에 켜서 데워두고 잘 때는 끄면, 보일러를 20도 정도로 낮춰도 돼서 작년 겨울에 요금이 꽤 줄었어요.', now() - interval '9440 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900023, 900001, '00000000-0000-4000-9000-000000000037', 7, '첫 김장 잘 마치셨네요 ㅎㅎ 저도 작년에 시어머니와 처음 김장을 했는데, 절이기부터 양념 바르기까지 내내 손이 얼얼해서 고무장갑은 정말 필수예요. 무릎패드나 낮은 스툴 하나 챙기면 허리가 훨씬 편하고요. 김치는 하루 정도 실온에 뒀다가 냉장고에 넣어야 제맛이라고 시어머니가 말씀하셨어요. 저는 이번 주말에 두 번째 김장이라 아직도 긴장되는데, 같이 힘내요!', now() - interval '9453 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900024, 900001, '00000000-0000-4000-9000-000000000041', 8, 'Notes I collected for my own first kimjang (my team is dragging me in next weekend): bring your own rubber gloves in your actual size because the shared ones are always too big and leak chili paste, wear clothes you can throw straight into the wash, and expect to be assigned the simple stuff like coating leaf by leaf — apparently nobody grades you on technique. Taking notes on the leave-it-out-for-a-day-before-the-fridge detail, that one I did not know.', now() - interval '9247 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900025, 900001, '00000000-0000-4000-9000-000000000025', 9, 'I do kimjang with the older women at my port every year, no problem about doing it wrong — one ajumma will just fix your hands mid-chop and tell you keep going. Bring rubber gloves, the thick kind, they usually have spares but the good ones go fast. And the tub is better after one day out of the fridge, don''t panic if it tastes too raw the first night. 👍', now() - interval '9343 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900026, 900003, '00000000-0000-4000-9000-000000000023', 1, 'Saya juga sedang berburu jaket tebal di lapak baju bekas dekat Okpo, teman satu dorm kemarin dapat jaket padded 10.000₩ kondisi masih rapat, tinggal dicuci dulu sebelum dipakai 😄 Kotak Pepero untuk banjang di line juga sudah saya beli, tinggal tunggu 11/11. Trik selimut listrik 30 menit lalu matikan memang benar, itu rutinitas di dorm kami supaya tagihan gas tidak meledak. Sabtu ini saya ikut kimjang bareng kelas Korea, semoga dapat bawa pulang kimchi seperti kamu.', now() - interval '9344 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900027, 900002, '00000000-0000-4000-9000-000000000010', 0, 'Congrats on landing the interview! For the cold, I''d wear the padded coat and pack your blazer flat in a tote, then change in a café or station restroom near the office — everyone does it and nobody blinks 😊 For the nerves, I shrink my self-intro down to three key points and rehearse them on the subway, and arriving 20 minutes early to sit and breathe helps more than any pep talk. One heads-up from my own D-10 search: companies tend to go quiet around year-end party season, so a slow reply doesn''t mean rejection — happy to swap self-intro feedback if you''d like a second pair of eyes! 🥲', now() - interval '9327 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900028, 900005, '00000000-0000-4000-9000-000000000045', 5, 'For once someone else is doing the flu shot nagging and I love to see it — I usually have to remind my whole group chat every November, eh 😅 For anyone wondering (someone asked above): the family clinic I went to near Haeundae just needed my ARC and NHIS card, no booking, in and out in 15 minutes, so for sure go before 10 while it''s quiet. And sending calm vibes to everyone teaching near a test site Thursday — my old hagwon kids are sitting suneung this year and I''m a nervous wreck refreshing the news like they''re my own ❄️', now() - interval '9348 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900029, 900004, '00000000-0000-4000-9000-000000000006', 11, 'Nhà mình dorm ở Hwaseong, ondol cũ y chang mà hoá đơn gas tháng này nhìn phát sợ luôn 😭 Mình chia sẻ mấy kèo đã test ở dorm: trước khi đi ca đêm chỉnh boiler sang chế도 외출 (đi vắng), về bật lại 20 độ có hẹn giờ, đỡ hơn giữ ấm cả ngày. Dán màng bong bóng lên cửa kính với nhét khăn cũ cuộn lại dưới khe cửa — không tốn đồng nào mà phòng giữ nhiệt hẳn. Chăn điện chỉ bật 30 phút trước khi ngủ rồi tắt, thấy lạnh quá thì úp thêm bình nước ấm. Tháng 11 mới là đợt đầu, ai cũng bị "thuế tháng 11" hết à, qua được đợt này tháng 12 sẽ đỡ thôi, cố lên mn 🌡️', now() - interval '9254 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900030, 900004, '00000000-0000-4000-9000-000000000004', 12, '저희 인천 집도 첫 한파에 보일러를 켜자마자 요금이 걱정돼서 고생했어요. 경험상 외출 모드로 두고 방문을 닫아 한 방만 데우고, 창문에 에어캡을 붙이고 문 아래 수건을 말아 끼우는 게 제일 효과가 컸어요. 전기요는 자기 30분 전에 타이머로 켜서 잠들면 저절로 꺼지게 하면 보일러도 덜 돌아가요. 11월 난방비는 다들 그렇지만 12월 중반쯤 누르니까 너무 조급해하지 않으셔도 돼요.', now() - interval '9171 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900031, 900004, '00000000-0000-4000-9000-000000000015', 13, 'Fellow old-villa dweller in Gyeonggi waving from Pyeongtaek — that first bill is absolutely the November tax, y''all, but you can outsmart it a little 😅 Biggest wins for us: keep the boiler on 외출 (out) mode when we''re gone instead of off, bubble wrap + thick curtains on the windows, and a rolled towel jammed under the door. Also good news on the electric blanket hunt — the market stalls and home-goods shops around Songtan usually have them for under 30,000 won, and ours pays for itself by letting the boiler sleep overnight. Hang in there, friend, December will be kinder! ❤️', now() - interval '9215 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900032, 900004, '00000000-0000-4000-9000-000000000008', 14, '우리도 전남 시골 단독주택이라 첫 한파에 고지서가 무서워요. 저희 경험으로는 보일러를 외출 모드로 두고 방문을 닫아 한 방만 데우는 게 제일 효과가 컸어요. 창문에 뽁뽁이 붙이고 문 아래에 낡은 수건을 말아 끼우면 돈이 거의 안 들어요. 비닐하우스는 밤마다 보온 부직포를 씌워주니 연료도 조금 덜 쓰네요 🙏', now() - interval '9160 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900033, 900005, '00000000-0000-4000-9000-000000000001', 6, '补充一个：校医院的流感疫苗一般不用预约，我11月初带上ARC和NHIS卡直接挂号就行，前后15分钟，价格和附近诊所差不多。去之前在官网确认一下当天的接诊时间就好。另外周四修学能力考试那天，考场周边早上7点就开始管制、公交绕行，我打算提前40分钟出门，避免被困在路上。😷', now() - interval '9018 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900034, 900004, '00000000-0000-4000-9000-000000000038', 15, '私もシンチョンの小さいワンルーム住まいで、初めての韓国の冬なので、今月のガス代を見るのが少し怖いです。窓にプチプチを貼って、ドアの下に丸めたタオルを置いたら、部屋が少し暖かくなった気がしました。ボイラーの「외출 모ード(外出モード)」という表現を初めて知ったので、ノートに書いておきました。電気毛布が市場なら3万ウォン以下で買えると聞いて、週末見に行ってみます ❄️', now() - interval '9108 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900035, 900004, '00000000-0000-4000-9000-000000000043', 16, 'Franchement tu me fais flipper d''avance, c''est exactement ma panique de la semaine 😭 Première facture de gaz dans mon one-room et le chauffage au sol reste une énigme totale, j''appuie sur des boutons au hasard et je prie !! J''ai déjà collé du film bulle de Daiso sur la fenêtre et une serviette roulée sous la porte, mais le fameux mode 외출 je sais même pas si mon vieux boiler l''a, quelqu''un sait à quoi ressemble le bouton exactement ? Et 20 degrés la nuit, ça suffit ou je risque de geler sur mon ondol ? Merci les amis 🙏❄️', now() - interval '9048 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900036, 900005, '00000000-0000-4000-9000-000000000029', 7, 'ARC болон NHIS картаа аваад ойрх 병원 рүү орвол захиалгаагүй 15 минутад дуусдаг, надад ч мөн адил байсан. Нэг жижиг зөвлөгөө: хийлгэсний дараа гараа хэвийн хөдөлгөж байвал өвдөлт бага байдаг, хавдсан хэсэгт хөргөсөн компресс түрхээд үзээрэй. Дадлага эхлэхээс өмнө ханиад хүрэхээс айж байгаа учраас би ч өнгөрсөн долоо хоног хийлгэчихсэн, арай л тайвширсан 😊 Pepero Day-дээ бүгдэд нь жижиг бэлэг бэлдээрэй 🍫', now() - interval '9075 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900037, 900002, '00000000-0000-4000-9000-000000000016', 2, '패딩 입고 이동하다가 회사 근처 편의점 화장실이나 카페에서 자켓으로 갈아입으면 됩니다. 겨울철 면접 다니는 사람 전부 그렇게 하니까 아무도 이상하게 안 봅니다. 자기소개는 전날 밤에 문장 다듬는 것보다 소리 내서 세 번 말해보고, 핵심 키워드 세 개만 외우는 게 훨씬 효과 있습니다. 그리고 20분 일찍 도착해서 로비에서 심호흡 한번 하고 들어가세요. 복장보다 눈 맞추고 끝까지 답변 마무리하는 게 훨씬 큽니다.', now() - interval '8986 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900038, 900003, '00000000-0000-4000-9000-000000000007', 0, 'Chuẩn luôn, mình cũng vừa chốt đơn áo phông 15k ở Đồng Miêu tuần trước, giống nhau kinh khủng 😭✨ Chăn điện bật 30 phút rồi tắt là đúng rồi đó, phòng mình làm vầy mà hoá đơn gas đỡ hẳn. 11/11 mình cũng mua Pepero nhỏ tặng bạn cùng lớp, hôm qua ăn thử loại hạnh nhân ngon lắm nha! Lạnh rồi mn giữ ấm mà vẫn để ý hoá đơn nha 🥶', now() - interval '8919 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900039, 900001, '00000000-0000-4000-9000-000000000042', 10, 'डरने की कोई बात नहीं यार 😅 इसी हफ्ते लैब के साथ मेरा भी पहला किमजाङ हुआ, अब सब मुझे ''किमची दीदी'' बुलाते हैं। जोरीगी (साल्टिंग) से लेकर सब अजुम्मानी खुद सिखाती हैं, बेचू काटने में गलती हुई तो बीच में आकर हाथ ठीक कर देती हैं न — कोई ग्रेडिंग नहीं होती। बस अपने साइज़ का मोटा गोमुजाङगअप (रबर दस्ताने) ज़रूर ले जाओ और वो कपड़े पहनो जो सीधे वॉश में चले जाएँ, मुरीकपेड घुटनों के लिए रखना। टिप: नया किमची पहली रात कच्चा लगता है — एक दिन शिलोन पर रखकर फिर नेङजाङगो में डालो, स्वाद ही अलग हो जाता है। शनिवार के बाद बताना ज़रूर, हल्मोनी के सामने वाली बात मत सोचो 😊', now() - interval '8936 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900040, 900001, '00000000-0000-4000-9000-000000000023', 11, 'Sabtu ini giliran saya kimjang pertama bareng kelas Korea di sini, gaskeun 😄 Sarung tangan karet ukuran sendiri sudah saya siapkan, dan teman di line yang pernah ikut menyuruh bawa pelindung lutut karena mencuci kol di lantai ternyata melelahkan juga. Tips ditinggal satu hari di suhu ruang sebelum masuk kulkas akan saya catat untuk teman-teman di dorm. Santai saja katanya, kalau salah memotong nanti dikoreksi bantu langsung, tinggal ikut saja.', now() - interval '8774 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900041, 900004, '00000000-0000-4000-9000-000000000022', 17, 'यो हप्ता मैले पनि ग्रीनहाउसको हिटर रातभर चलाउनुपर्‍यो, त्यसैले ग्यासको बिलको कुरा पढ्दा मन ढुक्क भएन। घरमा मैले गरेका सस्ता काम: बोयलरमा 외출 모드 (बाहिर जाँदा) हाल्ने, झ्यालमा बबल व्र्याप टाँस्ने र ढोकामुनि पुरानो कपडा थुन्ने। फार्ममा हामी भित्रपट्टि अर्को पातलो 비닐 तन्काएर हावाको तह बनाउँछौं, घरको झ्यालमा पनि त्यही तरिका राम्रो काम गर्छ। नोभेम्बरको बिल यस्तै बढ्छ, डिसेम्बरमा अलि घट्छ।', now() - interval '8778 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900042, 900004, '00000000-0000-4000-9000-000000000030', 18, 'Надад ч мөн адил нимгэн цонхтой өрөө бий, энэ долоо хоногийн тооцооноос айж байна. 외출 горимд шилжүүлээд цонхон дээр бөмбөлөг хальс нааж, хаалганы доор алчуур тавихыг өнөө шөнөөс эхэлье. Инчоны үйлдвэрийн хороолол орчимд цахилгаан хөнжил хямд зарах дэлгүүр байдаг уу? Би оройн ээлжтэй тул ажлаасаа гарчихад ихэнх дэлгүүр хаагдсан байдаг. Мэддэг хүн байвал хэлээч.', now() - interval '8819 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900043, 900005, '00000000-0000-4000-9000-000000000015', 8, 'Okay, this is officially the push I needed — I''ve been putting my flu shot off since the cold snap and I''ve got holiday travel coming up, so I''m fixin'' to go one morning this week before 10 like you said 🙌 My arm was sore for just one night last year too, totally worth it. Also love the suneung heads-up: my tutor''s students are testing Thursday and I''ve been quietly rooting for them all week, so I''ll keep my errands far away from any test sites that morning. Stay warm, y''all! ❄️💪', now() - interval '8757 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900044, 900004, '00000000-0000-4000-9000-000000000045', 19, 'Busan old-villa solidarity, eh 🥶 Same here — first cold snap and my one-room''s ancient boiler had the bill looking scary, so I finally caved and went electric-mat hunting. The market stalls near my place had them under 30,000 won, and combined with keeping the boiler on 예약 (timer) at 20 degrees instead of running it all evening, last winter''s December bill dropped way more than I expected. Bubble wrap on the windows is this weekend''s project too — apparently that''s the expat-teacher starter pack now 😅 The November tax is real, but it does get kinder, for sure.', now() - interval '8663 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900045, 900008, '00000000-0000-4000-9000-000000000007', 1, 'Chuẩn bị gọn ghế quá, mình mới tiêm cúm xong tuần trước luôn 🥶 Chỉ cần mang ARC với thẻ NHIS, vô quầy nói "독감 예방접종" là xong, mũi tự phí của mình ở phòng khám gần Hyehwa là 15,000₩, nhân viên check thẻ hết luôn không cần nói tiếng Hàn nhiều. Nên đi buổi sáng ít người, tiêm xong ngồi lại 15 phút theo dõi rồi về, tay hơi nhói xíu thôi chứ mai vẫn học vẫn đi làm bình thường. Mùa này cúm nhiều lắm, mn chốt lịch sớm nha 😊', now() - interval '8682 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900046, 900001, '00000000-0000-4000-9000-000000000033', 12, 'កុំភ័យណាបង អូនធ្លាប់ភ័យដូចគ្នាពេលដំបូង 🌶️ មីងៗមិនចាប់អារម្មណ៍ថាកាត់ត្រឹមត្រូវឬខុសទេ គេពានដៃកែឲ្យភ្លាមហើយប្រាប់ថាបន្តទៀត គ្មាននរណាដាក់ពិន្ទុចំណេះទេ។ គ្រាន់តែយកស្បែកដៃកៅស៊ូក្រាស់ទំហំផ្ទាល់ខ្លួន និងប៉ាដដាក់ជង្គង់ ព្រោះការលាងសណ្ដែកបាយនៅលើដីឈឺជង្គង់ណាស់ ហើយស្បែកដៃគេចែករំលែកជាធម្មតាតែទំហំធំនិងងាយលេចធ្លាយទឹកប្រហុត។ សៅរ៍នេះអូនក៏នឹងធ្វើគីមជាំងនៅផ្ទះម៉ាក់មាមប្ដីដែរ តោះស៊ូទាំងពីរនាក់ ❤️ បងទៅធ្វើជាមួយគ្រួសារគ្រូបង្រៀនមែនទេ?', now() - interval '8645 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900047, 900004, '00000000-0000-4000-9000-000000000028', 20, 'Grabe, this was me staring at our dorm gas meter this week 🥶 Our staff dorm boiler is managed by the office so I can''t even switch it to 외출 mode, so we went full seal mode instead — Daiso bubble wrap on the windows, rolled towels under every door gap, and honestly with the Jeju wind that made the biggest difference. Also an electric blanket on a 30-minute timer before bed, then off, and we all chipped in for one heated mat for the common room. Hays, hang in there — the ajumma at my neighborhood market swears the sting eases up once December settles in 🍂', now() - interval '8699 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900048, 900005, '00000000-0000-4000-9000-000000000018', 9, 'Поддерживаю, это мамино-куринское напоминание года! 🧡 Я прививалась в начале ноября в маленькой фэмли клынике рядом с кампусом — с ARC и картой NHIS, без записи, минут за 15 управилась, вышло около 25 тысяч вон, и рука болела всего вечер. Тоже советую идти до 10 утра: зашла перед лекцией и никого не было. И да, в четверг из-за сунёна моя смена в кафе сдвинулась — районы с экзаменами лучше объезжать заранее! Уколитесь все до 11/11, чтобы на Пеперо-дей держать коробки обеими руками, обнимаю 🍬', now() - interval '8616 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900049, 900004, '00000000-0000-4000-9000-000000000002', 21, '저희 식당도 첫 한파에 고지서 보고 한숨부터 나왔습니다. 낡은 보일러는 외출 모드 유지하고, 보일러 급수 압력이 1.0 밑으로 떨어져 있으면 난방수가 안 돌아서 열이 늦게 올라오니 1.5쯤 채워보세요. 이거 하나 확인했더니 저희 30석 가게도 확실히 덜 돌아갑니다. 마, 전기요 타이머 30분이랑 문풍지 조합은 12월 고지서에서 차이가 큽니다 👍', now() - interval '8626 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900050, 900004, '00000000-0000-4000-9000-000000000005', 22, '宿舍党举手！我的小房间晚上冷得像冰窖，刚买了人生第一个电热毯 🌊 睡前定时开30分钟、躺下就关，暖一整晚也不心疼电费；再买气泡膜贴住窗缝、拿旧毛巾卷起来塞门底，几乎零成本，早上明显没那么冷了。11月这一笔就当交学费，12月大家一起省回来吧 ❄️', now() - interval '8618 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900051, 900001, '00000000-0000-4000-9000-000000000006', 13, 'Đọc mà hào hứng quá! Cuối tuần này mình cũng chốt lịch kimjang ở trung tâm đa văn hoá gần nhà máy luôn, đúng dịp mà 🌡️🍲 Chưa làm bao giờ nên đang lén note lại mấy kèo từ comment mn: mang găng tay cao su đúng cỡ tay mình, mặc đồ dính ớt thoải mái, kể cả đệm gối ngồi chà báp cả ngày. Hy vọng được các cô chỉ từng bước như mọi người nói, kimchi thì ủ một ngày rồi cho vào tủ lạnh đúng kèo nha. Có kimchi mang về là ăn cả tuần hết hồ, quá hời!', now() - interval '8244 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900052, 900008, '00000000-0000-4000-9000-000000000030', 0, 'Баярлалаа, зөвлөгөө тус боллоо. ARC, NHIS картаа аваад бямба гарагийн өглөө эрт очихоор боллоо. Явахдаа "독감 예방접종" гэж хэлж, хийлгэсний дараа 15 минут сууна. Ойролцоогоор 15-25 мянган вон гэдгийг урьдчилан мэдэж байгаад санхүүгээ тооцоолоход хялбар боллоо.', now() - interval '8268 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900053, 900004, '00000000-0000-4000-9000-000000000035', 23, 'Бір бөлмелі үйде ескі еден жылытуы бар адам ретінде жауабым: үйден шыққанда бойлерді вечхуль режимінде қалдыр, үйге келгенде 20 градуске таймер қой — суық бөлмені қайта жылыту тәулік бойы жылытудан арзан. Терезеге көпіршік пленка, есік астына ескі сүлгі, ал төсектен 30 минут бұрын ғана электр көрпесін қосамын. Өткен жылы дәл осылай желтоқсан шотын шамамен үштен бірге түсірдім. Қараша салығы — бәрімізге ортақ, сенім бол, Желтоқсан ары қарай жұмсақ.', now() - interval '8273 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900054, 900010, '00000000-0000-4000-9000-000000000016', 1, '우리 팀 업데이트가 딱 11/11에 배포돼서 사무실용 페페로 박스를 통째로 들여놨습니다. 성수 팝업은 배포 안정화 끝나면 팀원들이랑 갈 예정인데, 인기 있는 곳은 예약 안 하면 한 시간씩 줄 서는 경우가 있으니 미리 확인해 보세요. 페페로 데이에 오븐까지 돌리신 걸 보면, 제 크런치도 견딜 만한 수준이었네요.', now() - interval '8073 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900055, 900008, '00000000-0000-4000-9000-000000000019', 2, '저도 처음으로 아파트 공동김장에 신청해서 일요일을 설레게 기다리고 있어요. 고무장갑 안에 얇은 면장갑 한 벌을 더 끼우면 뜨거운 양념도 안 느껴지고 손이 덜 시려요. 무릎패드랑 넉넉한 앞치마, 갈아입을 상의 하나 꼭 챙기시고 아침은 든든히 드시고 가세요, 옆자리 동네 아지매들이 진짜 속도를 붙여주실 거예요. 토요일 오전 독감주사 일정도 아주 잘 잡으셨어요, 하루만 지나면 김장에 무리 없을 거예요 ^^', now() - interval '8151 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900056, 900005, '00000000-0000-4000-9000-000000000036', 10, 'Спс за напоминание — записалась на пятницу утром, как раз до кимджанга в субботу. В четверг из-за сунына работаю из дома, так что объезды маршрутов вокруг экзаменов меня не заденут. Из прошлого года: с ARC и картой NHIS визит занял минут пятнадцать, рука болела только один вечер.', now() - interval '8119 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900057, 900008, '00000000-0000-4000-9000-000000000036', 3, 'У нас в компании тоже кимджанг, только в субботу — так что я в той же лодке: длинные резиновые перчатки и фартук уже куплены. Коллеги советуют солить слоями, а потом промывать листья раза три, иначе будет пересол. Сама капусту ни разу не солила, так что нервничаю не меньше вашего 🥲', now() - interval '8101 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900058, 900008, '00000000-0000-4000-9000-000000000002', 4, '독감 주사도 챙기고 제대로 준비하셨네요 👍 다만 주사 맞은 날은 팔이 아플 수 있으니 배추 나르는 무거운 일 말고 양념 버무리기 담당으로 자리 잡으세요. 옛날 방식처럼 맨손 말고, 고무장갑 안에 얇은 면장갑을 한 겹 더 끼면 양념도 안 느끼고 손도 덜 시립니다. 가족 얼굴 본다고 주말까지 일하시는 거, 고생이 많습니다. 김치 한 통은 꼭 챙겨 오시고요.', now() - interval '7975 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900059, 900001, '00000000-0000-4000-9000-000000000005', 14, '太羡慕了！这周末我也要跟语伴社去第一次김장，已经按大家的建议备好合手的胶皮手套和护膝了 😊 我奶奶在青岛每年立冬前也会腌一缸大白菜，味道虽然和泡菜不一样，但一家人一起忙活着过冬的感觉应该是相通的——就冲这个我也特别期待。"김장 화이팅!"这样说自然吗？我韩语还很一般，请多指教 ❄️', now() - interval '7985 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900060, 900004, '00000000-0000-4000-9000-000000000034', 24, 'Ай, я эту неделю тоже думаю только про газ — однушка, старый нампхан, а пуховик до сих пор не купила, сначала счёт, потом куртка 😅 Мой набор спасения: днём ставлю вечхуль режим, на ночь нампхан на 20° с йерым (таймером), за 30 минут до сна электронное одеяло и всё выключается само, а под дверь — полотенце в рулоне и пупырка на окно, копейки, а реально теплее, норм! Говорят, в декабре станет полегче, так что держись, подруга, эту ноябрьскую подать переживём вместе, обнимаю 🧡', now() - interval '7964 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900061, 900006, '00000000-0000-4000-9000-000000000013', 1, 'Sis, I was scared of the gas bill too after the first cold snap lol 😅 My Korean coworker taught me to turn the electric blanket on 30 minutes before bed and then switch it off, keep the floor heating low, and wear thick socks — my bill came out almost the same as October. And good luck vibes to all the kids taking the exam this week, our hotel goes into full quiet mode on suneung day too! 🍫', now() - interval '8039 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900062, 900005, '00000000-0000-4000-9000-000000000023', 11, 'Senin pagi habis shift malam saya langsung ke klinik keluarga dekat Okpo, cukup bawa ARC dan kartu NHIS, tidak perlu reservasi, 15 menit beres dan biayanya seperti yang kamu bilang 😄 Jam 8 masih sepi, pasien lokal baru rame jam 9-an, jadi datang pagi memang benar. Kamis jadwal bus memang berubah karena ujian, teman di dorm yang antar permintaan material sempat kaget santainya jalan. Lengan saya cuma pegal semalam, keesokan harinya sudah aman.', now() - interval '7831 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900063, 900005, '00000000-0000-4000-9000-000000000019', 12, '저도 지난주에 인천 동네 가정의원에서 맞고 왔는데, ARC랑 NHIS 카지만 가져가면 예약 없이 15분이면 끝나니까 오전 10시 전에 가시라는 팁 정말 맞아요. 목요일 수능엔 시험장 주변 오전 7시부터 도로 통제가 시작되서 저희 창고 배송 일정도 아침 시간대를 싹 뒤로 밀어놓고 기사님들한테 30분 일찍 출발하라고 공지했어요, 시험장 근처에서 일하시는 분들은 미리 확인해두시면 마음이 편해요. 이런 글 보고 한 분이라도 더 주사 맞으러 가신다면 참 좋겠어요 ^^', now() - interval '7812 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900064, 900001, '00000000-0000-4000-9000-000000000003', 15, '哈哈我上周刚跟韩国同事完成了人生第一次김장，抱回来整整两箱泡菜，对大婶们的手速佩服得五体投地 🍲 实用经验：一定要自己带合手的橡胶手套，外面再套一层一次性手套双层防辣，跪着腌白菜记得垫个坐垫或护膝，不然第二天膝盖真的会抗议。另外给楼下问的姐妹：''김장 화이팅!''这么说完全自然，韩国人天天把화이팅挂嘴边，放心去喊吧 ✊', now() - interval '7897 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900065, 900005, '00000000-0000-4000-9000-000000000022', 13, 'मैले पनि यो हप्ता गुन बोगनसो (군 보건소) मा फ्लू सुई लगाउने योजना बनाएको छु, ग्रीनहाउसको बिहानको काम सकेपछि जान्छु। ग्रीनहाउसका साथीहरूले भनेका छन्: ARC र NHIS कार्ड लिएर पुग्छ, बुकिङ चाहिँदैन र बिहान १० बजेअघि जाँदा लाइन छोटो हुन्छ। अर्को कुरा, हप्ताको दिन (सुनुङ) बिहान स्कुल नजिकको बाटो ७ बजेदेखि बन्द हुन्छ, म पनि त्यो दिन फार्मतिर साइडको बाटो रोज्नेछु।', now() - interval '7862 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900066, 900002, '00000000-0000-4000-9000-000000000036', 3, 'По опыту подготовки к интервью здесь: пуховик, пиджак в пакете, переодеваешься в туалете станции или кафе у офиса — в сезон все так делают, никто не удивится. Самопрезентацию собери как мини-кейс из трёх пунктов: кто ты, главный проект с результатом в цифрах, почему именно эта компания — и репетируй вслух по дороге, а не переписывай ночью. Приходи минут на 20 раньше и посиди в лобби: запас времени успокаивает лучше любых советов.', now() - interval '7826 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900067, 900004, '00000000-0000-4000-9000-000000000036', 25, 'Веду таблицу газовых счетов четвёртую зиму: прошлый январь был рекордным, поэтому в этом году электроодеяло купила заранее — включаю на таймере за 30 минут до сна и выключаю, счёт за ноябрь пока держится. Из работающего: режим 외출 на бойлере, когда ухожу, плюс полотенце в рулоне под дверь — в моей вилле со старыми окнами это дало заметную разницу. Ноябрьская надбавка у всех, декабрь обычно мягче.', now() - interval '7869 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900068, 900008, '00000000-0000-4000-9000-000000000039', 5, '저도 지난주에 한국 직원들과 첫 김장을 했는데, 준비물을 대박 완벽하게 챙기셨네요 👍 고무장갑 안에 솜장갑을 한 겹 더 끼우면 뜨거운 양념도 안 느껴지고 손이 훨씬 덜 시려요. 이름 적어 둔 김치통도 따로 챙기시고, 담은 김치는 하루쯤 서늘한 곳에 뒀다가 냉장고로 옮기는 게 제일 맛있더라고요. 토요일에 주사 맞고 일요일에 김장이면 하루 사이라 다행이에요, 팔 아픔도 하루면 금방 가니 걱정 마세요 😊', now() - interval '7843 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900069, 900003, '00000000-0000-4000-9000-000000000020', 2, '१५,००० वनमा पाडेड कोट — राम्रो डिल यार। चार वर्षअघि सेउल गएको बेला मैले पनि डोंगम्योबाटै ज्याकेट किनेको थिएँ, अझै चलिरहेको छ। इलेक्ट्रिक ब्लाङ्केट ३० मिनेट बालेर बन्द गर्ने तरिका हाम्रो डोर्ममा पनि चल्छ, तातो लुगा ओढेर सुत्दा ग्याँस बिल निकै घट्छ। र यो पटक पहिलो चोटि मैले पनि ११/११ मा सेक्सनका सबैलाई Pepero किनेर बाँडेँ, सबै खुशी भए।', now() - interval '7908 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900070, 900005, '00000000-0000-4000-9000-000000000004', 14, '저도 지난주에 인천 동네 가정의원에서 맞고 왔어요. 외국인도 건강보험증과 외국인등록증만 있으면 예약 없이 되는 곳이 많은데, 오전에 가니 줄이 짧아서 금방 끝났어요. 목요일 수능 날엔 저희 아이 학원 수업이 오후로 밀리기로 해서, 시험장 근처는 오전 일찍부터 도로 통제가 시작되니 등하원 시간을 30~40분 여유 있게 잡으려고요. 이런 글 올려주셔서 고맙네요, 다들 미리 챙겨서 편하게 보내요 ㅎㅎ', now() - interval '7699 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900071, 900008, '00000000-0000-4000-9000-000000000027', 6, 'Grabe, we''re kimjang buddies this weekend — my mother-in-law finally invited me to the family one after three years of marriage, and I''m just as nervous about keeping up with the ajummas as you! One tip from helping my neighbor last year: wear a big apron over your layers, and put thin cotton gloves UNDER the long rubber ones, because that cold salted cabbage makes your hands freeze so fast. Also bring an extra large bag — there is always kimchi to take home, always 😄 You got your shot Saturday morning so your arm will have a whole day to rest before the kimjang, sarap na sarap ka dito, fighting! 🥬💪', now() - interval '7759 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900072, 900011, '00000000-0000-4000-9000-000000000037', 1, '부산도 어제부터 해풍 바람이 정말 차가워서 겉옷 없이는 못 나가요. 전기요를 시장 노점에서 3만 원 아래로 사셨다고 하셨는데, 혹시 어느 시장인지 알려주시면 저도 오래된 집이라 이번 겨울 준비하느라 알아보고 있어서 감사하겠어요. 옆집 아주머니께서 주신 배추김치로 저녁이 해결된다니 정말 든든하시겠네요.', now() - interval '7698 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900073, 900008, '00000000-0000-4000-9000-000000000021', 7, 'Honestly this is the exact same week I''m having — the flu shot slots near my campus keep selling out before my afternoon classes end, so going Saturday morning like you planned is the smart move 😅 And no joke, it''s my first kimjang volunteer day this weekend too, and my senior just told me to bring thin gloves under the rubber ones and let the ajummas boss me around. Fighting to our arms, our hands and our gas bills 💪', now() - interval '7629 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900074, 900002, '00000000-0000-4000-9000-000000000002', 4, '패딩 입고 이동하다가 회사 근처 편의점이나 카페 화장실에서 자켓으로 갈아입으세요, 겨울에 면접 보는 사람들 다 그렇게 합니다. 콧물 흘리면서 추위 떨고 나가는 것보다 낫습니다. 자기소개는 밤새 고치지 말고 소리 내서 세 번 해보세요, 몸이 외우면 떨어도 입은 나옵니다. 그리고 20분 일찍 가서 로비에서 숨 한번 고르고 들어가세요, 화이팅 👍', now() - interval '7604 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900075, 900012, '00000000-0000-4000-9000-000000000007', 1, 'Busan thì mình không biết, nhưng Seoul tuần này lá vẫn đẹp lắm luôn — đường Đại học gần trường mình lá vàng rơi đầy vỉa hè, nghe nói cuối tuần có gió quét nên bạn tranh thủ đi sớm nha 🍂 Còn thứ Năm thi suneung, mình hồi hộp thay mấy bạn nhỏ luôn, vì năm sau nếu tiếng Hàn với tiền tiết kiệm đủ để chốt đơn đại học thì đến lượt mình ngồi bàn thi rồi 😭✨ Chúc mọi sĩ tử thi thật tốt, hôm đó phố im ắng mà xa xa nghe tiếng cổ vũ dễ thương ghê, mn cùng cầu may cho tụi nhỏ nha!', now() - interval '7616 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900076, 900006, '00000000-0000-4000-9000-000000000024', 2, 'Gais gue bukan orang Thai tapi gue satu vessel derita 😭😭 Mantel "musim dingin" gue dari Jakarta itu level kardigan doang, dingin kemarin tuh kehujanan beneran. Tips dari gue: electric blanket 30 menit sebelum tidur terus matikan, sumbat bawah pintu pakai handuk tua digulung, sama bubble wrap di kaca jendela — murah banget tapi beneran ngefek, tagihan gas gue kemarin bikin gue nangis saking mahalnya 🥲 Pepero Day juga bentar lagi, gue asik baca label di minimarket rame-rame, doain nemu yang gak ada gelatin-nya hahaha. Semangat buat adek yang suneung, hwaiting!! 🍫✨', now() - interval '7517 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900077, 900012, '00000000-0000-4000-9000-000000000016', 2, '서울 단풍도 이번 주가 끝판입니다. 저희 사무실 근처 성수 쪽 은행나무도 바람 한 번 불면 다 떨어질 단계라, 일요일 아침 일찍 가시는 게 정답입니다. 부산 금정산 상태는 저도 모르지만, 아침 해 뜨는 시간에 앉아서 보면 바람 몰리는 오후보다 확실히 낫습니다. 목요일 수험생분들 얘기 나온 김에, 저희 팀도 배포 검사장처럼 마음 졸이고 있으니 서로 화이팅입니다.', now() - interval '7525 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900078, 900006, '00000000-0000-4000-9000-000000000007', 3, 'Đừng lo hoá đơn gas quá bạn ơi, mình ở one-room cũ ở Seoul cũng hoảng y chang năm đầu 😭✨ Mấy kèo đã test: khi ra ngoài chỉnh boiler sang chế độ 외출 (đi vắng) thay vì tắt hẳn, để 20 độ có hẹn giờ, chăn điện chỉ bật 30 phút trước khi ngủ rồi tắt. Dán màng bong bóng lên cửa kính với nhét khăn cũ cuộn lại dưới khe cửa, Daiso bán mấy nghìn đồng thôi mà phòng giữ ấm hẳn, đắp thêm tất dày là ấm từ chân tới đầu luôn. Thứ Năm suneung mình cũng cầu may cho tụi nhỏ, năm sau nếu tiếng Hàn và tiền tiết kiệm đủ để chốt đơn đại học thì đến lượt mình ngồi bàn thi đó luôn 😭', now() - interval '7465 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900079, 900005, '00000000-0000-4000-9000-000000000021', 15, 'Honestly this is the push I needed — I''ve lost the campus health center slot race twice now because they sell out before my afternoon classes end, so before 10am it is. And no joke, watching the whole city slow down for the suneung kids Thursday morning is my favorite Seoul moment every year, rooting for all of them from the sidewalk ❄️💪', now() - interval '7456 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900080, 900008, '00000000-0000-4000-9000-000000000012', 8, 'ว้าววางแพลนดีมากเลยค่ะ ฉันก็กำลังกลัวเข็มวัคซีนหวัดอยู่เหมือนกัน ตอนนี้ยังไม่กล้าจองสล็อตเลย 555 แต่อ่านคอมเมนต์ด้านบนแล้วโล่งใจมาก แค่พก ARC กับบัตร NHIS ไปบอกว่า 독감 예방접종 ก็จบ ราคาแค่หมื่นห้าพันวอนเอง น้อยกว่าที่คิดไว้เยอะ 🥶 ส่วนคิมจังวันอาทิตย์อย่าลืมใส่ถุงมือผ้าบางๆ ไว้ใต้ถุงยางยาวก่อนนะคะ กะหล่ำเค็มเย็นๆ ทำให้มือแข็งเร็วมาก สู้ๆ ทั้งเข็มและคิมจังเลยค่ะ 🍁🍫', now() - interval '7543 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900081, 900004, '00000000-0000-4000-9000-000000000026', 26, 'Bes, same tayo — shared ang boiler sa dorm namin kaya hindi ko rin ma-switch sa 외출 mode, kaya ''seal mode'' na lang kami: bubble wrap sa bintana, rolled towel sa ilalim ng pinto, tapos electric blanket 30 minutes bago matulog tapos i-off agad. Grabe, halos triple din ang gas bill namin noong first cold snap kaya tipid mode muna tayo ngayong November 😭 Saka bes, pag punta ka sa clinic, magpa-flu shot ka na rin (독감 예방접종 — ARC at NHIS card lang dalhin mo, mga 15-25k won, minsan libre sa health center) bago pa humaba ang pila. Kaya natin ang November tax na ''yan, fighting! 💪❄️', now() - interval '7328 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900082, 900008, '00000000-0000-4000-9000-000000000020', 9, 'सुईको लागि क्लिनिकभन्दा बोगन्सो (보건소) पनि हेर्नुहोला — म यसै हप्ता गिमहेको बोगन्सोमा गएँ, बिहानै गएकोले लाइन छोटो थियो र बीमा कार्ड देखाएपछि धेरै तिर्नु परेन। काउन्टरमा ''독감 예방접종'' भने पुग्छ। किमजाङमा चाहिँ लामो रबर ग्लभभित्र पातलो कपडाको ग्लभ लगाउनुहोस्, नुनिएको चिसो बन्दाले हात चाँडै जम्छ यार।', now() - interval '7352 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900083, 900007, '00000000-0000-4000-9000-000000000035', 1, 'Мен де сенбі күні көпұлтты отбасы орталығында кимжанг жасаймын, биыл үшінші жыл. Тілін жақсы білмесең де қорқыма — ажуммалар сөйлесуге асықпайды, қолың қате кессе орта жолда түзеп, әрі қарай жүргізеді, ешкім бағаламайды. Өзіңе лайық қалың резеңке қолғап алып бар, киім жуылғыш болсын, тізеңе сүлгі немесе тізе жастығын төсе. Соңында жаңа кимчиден түпбек береді, жол ақысың да шығады.', now() - interval '7342 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900084, 900010, '00000000-0000-4000-9000-000000000010', 2, 'Cold weather making the butter behave is such a satisfying little win 😊 I''ve been saving a Seongsu Christmas pop-up trip as my reward for after my interview, so please report back on which ones are worth the queue — especially if any have a dessert counter for inspiration. As someone whose gas bill already doubled this week, I''m just grateful the cold snap is at least good for croissants 🥲', now() - interval '7223 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900085, 900010, '00000000-0000-4000-9000-000000000003', 3, '哈哈做营销的举手，我上周也去圣水踩点了几个圣诞快闪店找 campaign 灵感，人气店基本都要提前预约，工作日下午排一小时很正常，去之前记得先查预约制，外面排队是真冷 🥶 不过甜品灵感是真的多，我路过一个卖热红酒配巧克力挞的快闪摊挪不动脚，已经记进方案里了。可颂的分层做出来一定发图馋我一下！', now() - interval '7269 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900086, 900008, '00000000-0000-4000-9000-000000000044', 10, 'Baker here — we wear thin cotton gloves under the rubber ones all winter when handling cold dough, and it works exactly the same for salted cabbage, hands stay so much warmer 😄 Getting the shot the morning before kimjang is smart, one day of rest is plenty. Have fun, kimjang hands are a badge of honor here 🥐', now() - interval '7228 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900087, 900005, '00000000-0000-4000-9000-000000000005', 16, '我也刚在校医院约了这周的流感疫苗，正打算挑上午10点前去！听同学说带ARC和NHIS卡直接挂号就行，不用预约。进门说一句"독감 예방접종 하러 왔어요"应该就够了——这样说自然吗？我韩语还在学，请大家帮我改改 😊 周四수능早上考点周边有交通管制，大家出门记得提前一点哦 ❄️', now() - interval '7191 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900088, 900013, '00000000-0000-4000-9000-000000000029', 1, 'Айх хэрэггүй, 11 сарын төлбөр хүн бүрд ийм л өндөр байдаг 😊 Цахилгаан хөнжлөө уламжлалт захын лангуунаас гучин мянган вонд авсан, унтахаас 30 минутын өмнө таймер дээр асаагаад унтаж ормогц унтраадаг — шөнөжин бойлер ажиллуулахаас хамаагүй хэмнэлттэй. Гарахдаа бойлерыг 외출 горимд шилжүүлж, цонхонд бөмбөлөг хальс наагаад үз, өрөө илт халуунаа хадгалдаг болно. Би ARC, NHIS картаа аваад ойрын 병원 дээр томуугийн вакцин хийлгэсэн, 15–20 мянган вон л байсан — дадлагаас өмнө ханиадаас сэргийлэх нь хамгийн чухал шүү 🍂', now() - interval '7162 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900089, 900012, '00000000-0000-4000-9000-000000000023', 3, 'Saya di Geoje jadi tidak bisa melihat kondisi Geumjeongsan langsung, tapi di jalur bukit sekitar Okpo daunnya sudah hampir habis setelah angin Jumat — kalau mau mengejar sisa daun, pagi lebih aman sebelum angin naik lagi 😄 Sabtu ini saya juga kimjang pertama bareng kelas Korea, semoga cuacanya cerah di akhir pekan. Untuk adik-adik suneung Kamis, semoga perjalanan lancar dan hasilnya sesuai harapan.', now() - interval '6828 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900090, 900011, '00000000-0000-4000-9000-000000000025', 0, 'For the person asking, it''s the home-goods stall row on the Bujeon market side, they had a few styles all under 30,000 won. If that is too far, the stalls near the port side sell the same thing, no problem. Just check the plug and timer button works before you pay. 👍', now() - interval '6727 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900091, 900006, '00000000-0000-4000-9000-000000000011', 4, 'หนูเฮ็ดโรงเรือนสตรอว์เบอร์รีแถวอีชอน เดือนนี้เตาน้ำร้อน (보일러) เผาทั้งคืน บิลแก๊สขึ้นจนหน้าตื่นเลยเหมือนกัน 😭🔥 ที่บ้านหนู ตอนออกไปข้างนอกไม่ปิดเตาหมดนะ หมุนไปโหมด 외출 แล้วตั้งอุณหภูมิต่ำๆ ไว้ ผ้าห่มไฟฟ้า (전기요) เปิด 30 นาทีก่อนนอนแล้วปิด แปะบับเบิ้ลแร็ปหน้าต่าง ซื้อที่ไดโซ่แค่หลักพันวอนเอง ใส่ถุงเท้าหนาก็อุ่นสบายเลย ❄️ อีกอย่าง จดตัวเลขบิลแก๊สเดือนก่อนไว้เทียบ จะได้รู้ว่าขึ้นเพราะหนาวจริง ฮาอิทิงให้น้องคนสอบด้วยน้า 🍓', now() - interval '6759 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900092, 900013, '00000000-0000-4000-9000-000000000017', 2, 'Aka, bu tashvish menga ham tanish — bizning yotoqxonaning isitish tizimi ham qadimiy. Tajribam: uxlashdan 30 daqiqa oldin boiler taymerini qo''yib o''chiraman, eshikka munpungji yopishtirganim xonani ertalabgacha issiq saqlayapti. Yostiq ostiga issiq suv idishi qo''yib yotsam, tun bo''yi isitish shart emas — o''tgan qishda gaz hisobi shu tufayli oyiga 15 ming won atrofida kam chiqar edi. Gun bogeonso''dagi gripp emagi uchun ARC va NHIS kartani olib ertalab 10 dan oldin boring, men shu hafta navbatda turdim, 15 daqiqada bo''ldi, qo''l bitta kechagina og''ridi.', now() - interval '6834 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900093, 900013, '00000000-0000-4000-9000-000000000014', 3, 'Don''t run the boiler all night — I set mine to cut off about an hour after I fall asleep and come back on before I wake up, and that alone kept my gas bill from jumping last winter. A cheap electric blanket on a 30-minute timer plus a hot water bottle under the covers covers the coldest hours, and the thin insulation sheet on the windows really does cut the draft more than you''d expect. Good luck with the flu shot, and the kimchi from your landlady sounds like the coziest way to head into winter. :)', now() - interval '6686 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900094, 900013, '00000000-0000-4000-9000-000000000019', 4, '저도 첫 해에 똑같이 겁먹었는데, 보일러는 외출 모드로 두고 잠들기 30분 전에 전기요를 틀었다 끄는 것만으로 충분했어요, 시장 노점이면 3만 원 아래로 삽니다. 창문에 뽁뽁이 붙이고 문 밑에 젖은 수건 말아 끼우고 베개 옆에 더운물병 하나 두면 밤새 보일러를 돌리지 않아도 됩니다. 독감주사는 꼭 이번 주에 받으세요, ARC와 NHIS 카지만 있으면 가정의원에서 예약 없이도 15분이면 끝나요. 어머님이 보내주신 김치 두 동이면 밥 걱정은 없으니 겨울 준비 다 끝난 거예요 ^^', now() - interval '6682 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900095, 900013, '00000000-0000-4000-9000-000000000036', 5, 'Из опыта четырёх зим: на ночь грейте не комнату, а себя — электроодеяло с таймером (на рынках до 30 тысяч вон; берите с маркировкой KC и автовыключением, это безопасность, а не маркетинг). Включили за 30 минут до сна, уснули — само выключается, и газ почти не тратится. Днём режим 외출 на бойлере, пока вас нет, плюс полотенце в рулоне под дверь — в моей вилле со старыми окнами это дало самую заметную разницу.', now() - interval '6693 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900096, 900014, '00000000-0000-4000-9000-000000000010', 1, 'Happy to help build your map! Seongsu itself is honestly thin for halal — the closest thing I trust is a Turkish kebab spot near Seoul Forest station, and for South Asian food I''d just cross the river to Itaewon, where the choices are endless 😊 One label tip for the pop-ups: watch for 젤라틴 (gelatin) and any 알코올 in syrups and the mulled wine stalls, since festive desserts love hiding both. I''m saving Seongsu for after my interview next week, so I''ll report back anything halal-friendly I spot — fighting on your finals! 🥲', now() - interval '6669 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900097, 900012, '00000000-0000-4000-9000-000000000027', 4, 'I can''t help with Geumjeongsan, but Seoul side it''s the same story — the ginkgo trees near my academy in Nowon dropped half their leaves after Thursday''s wind, so your Sunday morning plan is the right one, don''t wait for the afternoon! Grabe, our family kimjang is this Saturday too, my first with my mother-in-law after three years of marriage, so we''re in the same boat learning from the ajummas — one tip from helping my neighbor last year: thin cotton gloves UNDER the long rubber ones, that cold salted cabbage freezes your hands so fast. And sending courage to the suneung kids on Thursday, my tutoring students are so buried in practice tests I''ve kept our lessons extra light this week 🍂🥬', now() - interval '6577 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900098, 900015, '00000000-0000-4000-9000-000000000018', 1, 'Какой же полезный разбор, спасибо — я как раз неделю охочусь за одеялом! 😍 Главное, оказывается, таймер авто-отключения (1/2/4 часа), а не уровни тепла — я чуть не купила модель без таймера, хорошо что увидела твой пост. В четверг из-за сунёна тоже выхожу после 9:10, моя смена в кафе сдвинулась, так что памятка про дороги прямо в точку! Напиши потом, какой вариант с таймером взял и почём — иду в выходные на рынок, хотя, наверное, сама кимчхи слепить умею лучше, чем чинить одеяло, обнимаю 🧡', now() - interval '6569 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900099, 900012, '00000000-0000-4000-9000-000000000008', 5, '전남 시골도 금요일 바람 한 번에 길가 은행잎이 거의 다 떨어졌어요, 그러니까 일요일 아침 일찍 가시는 게 정답 같아요. 바람 센 날엔 저희 비닐하우스 밧줄도 다시 조이는데, 단풍은 오후보다 아침이 확실히 낫더라고요. 저도 토요일에 시어머니랑 김장이라 서로 응원하고요, 갓을 좀 따로 덜어서 베트남식 절인 갓을 담가볼 거예요. 목요일 수험생 여러분도 좋은 결과 있길 응원할게요 🙏', now() - interval '6535 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900100, 900015, '00000000-0000-4000-9000-000000000014', 2, 'Great breakdown — I run the same 예약 timer setup in my officetel (heating only morning and evening, one room, door shut) and it''s honestly what keeps my gas bill from doubling in December. For Thursday: my academy in Gangnam is also delaying first classes and my bus reroutes around a test site, so tbh anyone with a morning commute should check their route tonight, not Thursday. One extra blanket tip from market shopping: test the plug and the timer button in the stall before you pay, not at home. Good luck with kimjang — my first one with my landlady''s family is this weekend too, may our backs survive!', now() - interval '6398 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900101, 900015, '00000000-0000-4000-9000-000000000019', 3, '배송 일정 짜는 사람으로서 목요일 알림에 일표예요, 시험장 주변은 오전 7시부터 통제가 시작되서 저희 창고 배송도 전부 10시 이후로 미뤄놓고 기사님들한테 미리 공지했어요. 전기요는 타이머 자동꺼짐이 핵심이라는 말에 완전 동의하고, 시장 노점에서 살 때는 결제 전에 타이머 버튼이 진짜로 눌리는지 꼭 눌러보세요. 토요일 김장엔 무릎패드가 짐보 필요하니 챙겨가시고, 허리 무사히 지키시길 바랄게요 ^^', now() - interval '6391 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900102, 900008, '00000000-0000-4000-9000-000000000022', 11, 'मालिक्नीसँग किम्जाङ गर्दा सिकेको कुरा बाँड्छु: रबरको ग्लाभ्सभित्र पातलो सुतीको ग्लाभ्स लगाउनुहोस्, नुनिएको चिसो बन्दा हात छिटो चिसिन्छ। बन्दा बाकस भर्दा जोडले थिच्नुहुँदैन, गल्ती गरे पनि अजुम्माहरू बीचमै आएर हात ठीक गराइदिन्छन्। सुई लगाएको दिन भने आराम गर्नुहोस्, हात सामान्यतया एक रात मात्र दुख्छ। फर्कँदा किम्चीको डल्लो अवश्य लिनुहोस्।', now() - interval '6383 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900103, 900015, '00000000-0000-4000-9000-000000000010', 4, 'Saving this whole post — I put bubble wrap on my studio window after my gas bill doubled, plus a rolled towel under the door, and I can confirm the room holds heat noticeably longer 😊 The electric blanket tip is exactly what I needed: I was planning to buy one this weekend and had only been comparing price and size, so the auto-off timer is now first on my checklist. And thank you for the suneung commute note — I have applications floating around Thursday and my study group meets that morning, so I''ll schedule everything after 10 and check my route tonight like you said. Hope your back survives kimjang on Saturday! 🥲', now() - interval '6407 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900104, 900001, '00000000-0000-4000-9000-000000000032', 16, 'សប្តាហ៍នេះខ្ញុំក៏នឹងធ្វើគីមជាំងជាមួយគ្រួសារចៅហ្វាយផងដែរ ជាលើកដំបូង ចិត្តភ័យបន្តិចតែរីករាយណាស់។ បានអានគន្លឹះទាំងអស់រួច ខ្ញុំទិញស្រោមដៃកៅស៊ូសមនឹងដៃខ្លួនឯង និងខ្នើយជង្គង់រួចហើយ ព្រោះត្រូវលាងស៊ាងលើដីត្រជាក់អស់ពីរបីម៉ោង។ គន្លឹះទុកគីមជីនៅសីតុណ្ហភាពបន្ទប់មួយថ្ងៃមុនដាក់ទូទឹកកក ខ្ញុំកត់ត្រាទុកចាំជាក់ឡើយ 🙏', now() - interval '6466 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900105, 900004, '00000000-0000-4000-9000-000000000011', 27, 'โรงเรือนสตรอว์เบอร์รีหนูที่อีชอนตอนหนาวต้องเปิดเตาเผา (보일러) ทั้งคืน ค่าน้ำมันขึ้นโหดเหมือนกันเลย 😭🔥 ทริคที่ได้ยินจากพี่อาจุมมา: อย่าปิดเตาหมดนะ ตั้ง 예약 คุมอุณหภูมิต่ำๆ ไว้จะถูกกว่าปล่อยห้องเย็นสนิทแล้วเผาใหม่ ส่วนตอนอ่านใบแก๊สให้ดูช่อง 사용량 (㎥) เทียบกับเดือนเดียวกันปีก่อน ถ้าใช้เท่าเดิมแต่ยอดพุ่งแปลว่าโดนอัตราค่าแก๊สขึ้น ไม่ใช่เราสิ้นเปลืองเอง สู้ๆ กับภาษีเดือนพฤศจิกายนนะ 🍓', now() - interval '6467 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900106, 900010, '00000000-0000-4000-9000-000000000011', 4, 'หนูยังไม่เคยไปเซงซูเลยค่ะ จากอีชอนถือว่าไกลมาก 555 รอดูรูปครัวซองต์กับร้านคริสต์มาสนะคะ 🥐 ช่วงนี้สตรอว์เบอร์รีในโรงเรือนกำลังเริ่มแดงพอดีวันเปโปโร เจ้าของฟาร์มแจกคิมจีที่ภรรยาทำมาด้วย อากาศเย็นแบบนี้เนยตั้งตัวดีพอดีเลย อร่อยแทนหนูด้วยนะ 🍓❄️', now() - interval '6448 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900107, 900012, '00000000-0000-4000-9000-000000000004', 6, '부산은 멀어서 금정산 단풍은 못 봐드리지만, 인천 동네는 금요일 바람 한 번에 은행잎이 거의 다 떨어졌어요. 그러니 일요일 아침에 가시는 계획이 정답 같아요. 저도 지난주에 시어머니와 김장을 끝냈는데, 양념을 전날 미리 만들어 두고 절인 배추는 물기를 꼼꼼히 빼두니 당일 작업이 훨씬 수월했어요. 냉동실 가득 찬 김치통을 보니 뿌듯하네요 ㅎㅎ 목요일 수험생 여러분 모두 좋은 결과 있길 응원합니다.', now() - interval '6309 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900108, 900015, '00000000-0000-4000-9000-000000000027', 5, 'Grabe, saving this whole post — our old ondol in Nowon is exactly the money-eating type, and after the first cold snap my husband and I just stared at each other over the bill 😅 What worked for us so far: 외출 mode when we''re both out, 예약 for early morning only, and I put bubble wrap on the bedroom window last weekend — the floor really does hold warmth longer now. Thank you for the auto-off timer tip on the electric blankets, I was about to just grab the cheapest one at the market, now the timer button is my first check. And as a tutor I can confirm Thursday chaos: I moved all my lessons to the afternoon and told my adult students the same thing you said — check your route tonight, not Thursday morning. Good luck with kimjang Saturday, mine is my first with my mother-in-law this weekend and I''m excited and lowkey scared for my back, fighting! 🥬💪', now() - interval '6354 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900109, 900001, '00000000-0000-4000-9000-000000000038', 17, '「김장 화이팅!」が自然かどうかという質問、私も気になっていたのでコメントします。語学堂の先生に聞いたところ、화이팅は日常のあちこちで使われる言葉なので、김장 화이팅!でもまったく自然だそうです。私も週末に語学堂の国際交流プログラムで初めての김장に参加予定なので、サイズの合うゴム手袋と膝パッドのアドバイスを早速ノートに書き込みました 🍂', now() - interval '6158 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900110, 900017, '00000000-0000-4000-9000-000000000018', 1, 'Срочно отвечаю, я как раз та, чью смену в кафе сдвинули из-за сунёна! 😅 В четверг утром метро — самый надёжный вариант, но на время аудирования (около 8:40) поезда на несколько минут встают, так что выезжай заранее и закладывай запас минут на 20. Автобусы возле экзаменационных пунктов обходят, а дороги возле школ блокируют с 7 утра, такси — лотерея, у меня подруга в прошлом году полчаса ждала. Советую либо перенести встречу на после обеда, либо выехать до 8:30 и спокойно посидеть в кафе у клиента — так спокойнее и для себя, и для детей на экзамене! И да, в субботу иду на кимджанг с местной группой, после расскажу как прошло — и Т-4, вытяни свой газовый счёт, обнимаю 🧡', now() - interval '6239 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900111, 900012, '00000000-0000-4000-9000-000000000012', 7, 'ฝั่งโซลใบไม้ยังสวยอยู่เยอะค่ะ รอบยอนเซแถวชินชนบ้านฉันต้นแปะก๊วยยังเหลือใบเหลืองเพียบ แต่ลมเมื่อคืนเริ่มแรงขึ้นเรื่อยๆ แล้ว ต้องรีบไปถ่ายรูปให้ได้สุดสัปดาห์นี้ก่อนใบหลุดหมด 🍁 วันอาทิตย์เช้าๆ ถูกที่สุดแล้วค่ะ ฉันกะวางแพลนไปชมใบสุดท้ายแล้วแวะงานคริสต์มาสป๊อปอัพที่ซองซูต่อเลย 555 ส่วนพฤหัสสุเนิงก็อย่าลืมเช็คเส้นทางกันนะคะ ขอให้น้องๆ สอบได้คะแนนดีๆ ด้วย 🥶', now() - interval '6207 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900112, 900017, '00000000-0000-4000-9000-000000000040', 2, '「正好是修學能力考試(수능)當天」という部分に、経験からお答えします。수능当日の午前は試験会場の周辺でバスの迂回や交通規制があって、タクシーもなかなかつかまらないので、会議を午後に変更するのが一番安全だと思います。私もその日はアパートの近くのバス路線が変わるため、午前中の移動は避けるつもりです。どうしても午前に出る必要がある場合は、地下鉄を利用して、普段より1時間以上の余裕を持って出発することをお勧めします。', now() - interval '6205 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900113, 900004, '00000000-0000-4000-9000-000000000041', 0, 'To the person asking what the 외출 button looks like: on most Korean boilers it''s literally written 외출 on the panel (some old wall units just have a door/leaving icon), and if yours is too old to have it, drop the temperature dial to minimum instead of switching it off completely. 20°C with 예약 is enough at night in my one-room — the electric blanket covers the last 30 minutes. One more thing worth checking: if the room heats up slowly, look at the boiler''s water pressure gauge and refill to about 1.5 bar; under 1.0 it runs longer for less heat, which is exactly the silent bill-eater on old villas.', now() - interval '6050 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900114, 900006, '00000000-0000-4000-9000-000000000018', 5, 'Хаи, сестричка, я каждую осень в Сеуле одно и то же — первый холодный воздух как удар под дых! 😄 Мой проверенный набор: нампхан на ночь ставлю на 20° с таймером (ечхак), а за 30 минут до сна включаю электрическое одеяло — оно само выключается, и газ почти не тратится. Пупырку на стекло и полотенце в рулоне под дверь — из Дайсо за копейки, а держат тепло лучше толстого пуха! Пуховик за 30 тысяч — зор, молодец, я свой тоже на рынке взяла, от нового не отличишь. В четверг пожелаем удачи малышам на сунёне, а на 11/11 кидай Пеперо всем подряд — самый дешёвый способ стать любимцем группы, хех! Обнимаю 🧡', now() - interval '6055 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900115, 900007, '00000000-0000-4000-9000-000000000026', 2, 'Bes, huwag kang kabahan sa Korean — first kimjang ko lang last week at turo at ngiti lang ginawa ko, iko-correct ka ng mga ajumma sa gitna tapos tuloy ulit, walang humuhusga 😄 Tips ko: manipis na cotton gloves muna BAGO ang mahabang rubber gloves kasi namumuo talaga kamay ko sa malamig na asin, tapos malaking apron sa ibabaw ng layers at knee pad o nakatiklop na kumot sa tuhod. At huwag kalimutan ang extra large na bag — laging may iuuwi kang kimchi, grabe, buong bucket ang uwi ko noong isang linggo 😂 Saka bes, pag may time ka next week, magpa-flu shot ka na rin habang hindi pa mahaba ang pila sa health center. Kaya mo ''yan, fighting! 🥬💪', now() - interval '5934 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900116, 900013, '00000000-0000-4000-9000-000000000032', 6, 'ខ្ញុំក៏ធ្វើការនៅផ្ទះស្មៅព្រំស្លាប់ក្នុងកៃវ៉ុងគី ហើយគ្រឿងភ្ញាក់ក្ដៅក្នុងបន្ទប់ខ្ញុំក៏ចាស់ដែរ ដូច្នេះចំណាយហ្គាសជាកង្វល់របស់ខ្ញុំដែរ។ វិធីខ្ញុំ៖ ប្រើមុខងារ 예ះករក្ដៅ ឲ្យវាបិទដោយខ្លួនឯងបន្ទាប់ពីគេងបានប្រហែល ៣០ នាទី ហើយបើកឡើងវិញមុនភ្ញាក់ប្រហែល ៣០ នាទី ដូច្នេះមិនខ្ជះខ្ជាយហ្គាសទាំងយប់ទេ។ បិទភក់នៅលើបង្អួច រូលខ្នើយវាយនៅក្រោមទ្វារ ហើយដាក់ប្រអប់ទឹកក្ដៅក្រោមភូមា ចំណេរពេលព្រឹកទៅធ្វើការនៅផ្ទះស្មៅ សម្លៀកបំពាក់ជាន់ច្រើនស្រទាប់ ៤ ក្ដៅជំនួសការបើកក្ដៅខ្លាំង។ ភូមាអ៊ីឡេអ្នកក្ដៅថោកក្រោម ៣ម៉ឺនវ៉ុនក៏បានដែរ ប៉ុន្តែត្រូវពិនិត្យមើលថាវាមានពេលវេសកាត់ស្វ័យប្រវត្តិ និងសញ្ញា KC ដូចមិត្តនៅខាងលើបាននិយាយ 🙏', now() - interval '5892 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900117, 900017, '00000000-0000-4000-9000-000000000019', 3, '매년 수능 날 배송 일정을 짜는 입장에서 말씀드리면, 회의를 오후로 옮기는 게 제일 확실해요. 아침에 가야 한다면 지하철로 오전 8시 반 이전에 도착해 근처 카페에서 기다리세요, 8시 40분쯤 청각평가 때 지하철이 몇 분 멈추니 그 전에 내려있어야 해요. 버스는 시험장 주변 우회로 빠져 시간 계산이 안 되고, 택시도 학교 앞 통제 때문에 기다리다 막히는 경우가 많습니다. 저희 창고도 목요일 배송은 전부 10시 이후로 미뤄놓고 기사님들에게 공지했어요.', now() - interval '5799 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900118, 900017, '00000000-0000-4000-9000-000000000027', 4, 'Online, grabe, I''ve been through this every year as a tutor — move the meeting to the afternoon if you can, because Thursday morning near any school is chaos: buses reroute from around 7am, roads by test sites are blocked, and taxis are basically a lottery. If it really can''t move, go by subway and leave at least an hour earlier than feels reasonable, since trains briefly pause around 8:40 for the listening test and the stations near schools get packed. I pushed all my Thursday lessons to after lunch for the same reason, and honestly sitting in a café near the client''s office working calmly beats a stressful squeeze. Sarap na sana kimchi menu mo hanggang Sunday, and may our backs all survive kimjang season 🥬💪', now() - interval '5777 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900119, 900007, '00000000-0000-4000-9000-000000000005', 3, '别担心韩语！我这周六也要跟语伴社去人生第一次김장，一样紧张 😊 大家总结的经验是：薄棉手套先戴在里面、外面再套长橡胶手套，膝盖下垫护膝或叠好的毯子，穿不怕辣油的衣服。据说就算做错，旁边的阿姨也会直接上手帮你改正，没有评分这回事。明天加油，김장 화이팅！ ❄️', now() - interval '5871 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900120, 900018, '00000000-0000-4000-9000-000000000034', 1, 'Ой, спасибо огромное, сохраняю на субботу — иду на свой первый кимджан с одногруппниками из лабы, теперь буду выглядеть умной со своими цифрами 😄 Записала: 10 кочанов = примерно 2,5 кг крупной соли, солим между листьями и переворачиваем через 5–6 часов, норм! Кому тоже впервые, как мне: все советуют брать свои резиновые перчатки по размеру (общие протекают от кочуткару!) и наколенник — колени скажут спасибо 🙏 А если кто знает, что такое ёмдо и надо ли нам мерить солёность рассола — напишите, пожалуйста, вся лаба будет благодарна! Кимджан хваитинг! 🥬💪', now() - interval '5804 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900121, 900001, '00000000-0000-4000-9000-000000000028', 18, 'Ours is this Friday with the kitchen crew and this thread has me excited and lowkey scared for my back 😂 Last year''s lesson: bring your own rubber gloves in your actual size because the shared ones leak chili paste grabe, plus a knee pad since you end up on the floor for hours. And to the teacher worried about doing it wrong in front of the halmoni — don''t be, our sous chef literally grabbed my hands mid-coating last year and fixed them, nobody grades you, the ajummas run the whole show. I''m packing extra kimbap for the crew because kimjang day always turns into a whole potluck hays 🥶🍂', now() - interval '5783 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900122, 900015, '00000000-0000-4000-9000-000000000029', 6, 'Энэ постыг хадгаллаа, таймерын зөвлөгөө яг зөв 😊 Сувилагчийн оюутан хүнээс нэг зүйл нэмье: авто-унтраалгагүй хямд загварыг шөнөжин өндөр дээр асааж унтвал өглөө бие хуурайшиж, арьс цочирдог тул KC тэмдэгтэй, таймер бүхийг сонгоорой. Боилерийн даралтыг 1.5 болгож шалгах зөвлөгөө хамгийн үнэтэй санагдлаа — манай хуучин виллад ч ийм л асуудал байж магадгүй байлаа. Практик дээр өвчтэй очихгүй байхын тулд бүгдээ томуугийн вакцинаа аваач 😊', now() - interval '5831 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900123, 900018, '00000000-0000-4000-9000-000000000040', 2, '「궁금해서 그런데 ''염도''가 무슨 뜻이에요?」の質問にお答えします。염도とは塩分濃度のことで、水1リットルに対して塩が何パーセント溶けているかを表します。私も初めてのキムジャンに備えて調べたのですが、白菜を塩漬けする段階の塩水はだいたい2〜3％、仕上がったキムチは1.5〜2％程度が目安だと読みました。実験と同じで数字で確認するのが一番安心なので、私は日用品店で安い염도계を買って試してみるつもりです。10頭に粗塩2.5kgという比率の共有はとても参考になりました。', now() - interval '5711 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900124, 900019, '00000000-0000-4000-9000-000000000007', 1, 'Chốt đơn kiểu này đúng mn rồi, mua 2 tặng 1 mà rẻ gần nửa so với mua lẻ là quá hời luôn 🥭✨ Mình cũng vừa mua Pepero nhỏ tặng bạn cùng lớp tiếng Hàn, 11/11 chia nhau vui hết hồ! Hoá đơn gas tháng này nhìn tay run thì mình hiểu cảm giác lắm 😭 Kèo 외출 mode với chăn điện 30 phút bạn làm rồi là chuẩn, mình làm thêm cái dán màng bong bóng lên cửa kính với nhét khăn cũ cuộn dưới khe cửa, được vài nghìn đồng mà phòng giữ ấm hẳn. Kimjang cuối tuần mà ai đi chung nhớ mặc găng cotton mỏng bên trong găng cao su dài nha, bắp cải ngâm lạnh làm tay lạnh hộc tốc, mình học được kèo này từ mn trên đây luôn 😊 Chúc bạn đi vui, có kimchi mang về là ăn cả tuần hời to!', now() - interval '5739 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900125, 900014, '00000000-0000-4000-9000-000000000024', 0, 'Makasih banget, notes-nya langsung gue caplok!! 😆 Tips 젤라틴 sama 알코올 di sirup itu beneran nyelametin — gue hampir kebobolan sama minuman hangat mulled wine pop-up kemarin. Kebab Turki deket Seoul Forest gue incar buat cek langsung, kalau bahannya aman langsung gue tempel di peta buat temen-temen baru. Sementara butuh Asia Selatan sih gue tetap nyebrang ke Itaewon, tapi doain Seongsu akhirnya masuk peta ya 🥹 Semangat interview-nya juga, hasilnya gue tunggu! 🍫✨', now() - interval '5691 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900126, 900015, '00000000-0000-4000-9000-000000000031', 7, '타이머 자동꺼짐이 핵심이라는 말 너무 공감해요 😊 저희 식당도 보일러를 아침·저녁 예약으로만 돌리고 문 앞에 두꺼운 커튼을 쳤더니 이번 달 고지서가 생각보다 덜 무서웠어요. 목요일 수능 날엔 저희 가게도 열 시에 열려고 해요, 바로 옆이 시험장이라 수험생들이 쉬게 해주고 싶거든요. 토요일 김장은 저도 사장 노릇 처음이라 떨리는데, 허리 무사하시길 서로 응원해요 🍲', now() - interval '5684 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900127, 900019, '00000000-0000-4000-9000-000000000031', 2, '페페로 2+1로 야간조까지 챙겨주시는 마음이 예뻐요 😊 저도 11/11에 알바생들한테 박스 몇 개 뿌렸는데 반응이 좋아서 다시 사러 갔어요. 가스비는 저도 고지서 보고 손이 떨렸는데, 외출 모드 꿀팁 잘 갖갑니다. 토요일 김장 응원할게요, 절임배추 만질 때는 고무장갑 안에 얇은 면장갑 한 겹 더 끼우면 속손이 덜 시려요 🍲', now() - interval '5706 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900128, 900008, '00000000-0000-4000-9000-000000000029', 12, 'Амжилт хүсье, би анхныхаа дараа жил нь дахин хийсэн дурсамжтай 😊 Резинэн бээлийний доор нимгэн хөвөн бээлий өмсөөд үз — нэрмэл байцаа хүйтэн тул гар хүргэлгүй тэсвэрлэхэд их тусалдаг. Томуугийн вакциныг ARC, NHIS картаа аваад ойрх 병원 рүү өглөө 10 цагаас өмнө очвол захиалгагүй 15–20 мянган вонд дуусдаг, надад ч мөн адил байсан. Дадлага эхлэхээс өмнө биеэ хамгаалах нь хамгийн чухал, кимжангаасаа кимчинь аваачиж март 🍂', now() - interval '5707 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900129, 900011, '00000000-0000-4000-9000-000000000009', 2, 'Lạnh thế thì mua chăn điện là chuẩn luôn 👍 Mình ở Daegu, đầu tuần vừa mua chăn điện có hẹn giờ ở khu đồ gia dụng chợ Seomun với giá hơn 20.000 won thôi, bật 30 phút trước khi ngủ rồi tự tắt nên hóa đơn gas không tăng mấy. Phòng mình gió lùa mà đêm nào cũng ngủ ấm, mọi người nên sắm sớm đi, càng lạnh giá sẽ càng leo thang 🥶', now() - interval '5333 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900130, 900018, '00000000-0000-4000-9000-000000000023', 3, 'Pas banget, Sabtu ini saya ikut kimjang pertama bareng kelas Korea di sini, jadi rasio 2,5 kg garam kasar untuk 10 kepala kol langsung saya catat 😄 Ditabur rapi di sela daun lalu dibalik setelah lima-enam jam, akan saya cek juga ke ibu-ibu di acara kalau takarannya sama. Sarung tangan karet ukuran sendiri dan pelindung lutut sudah masuk tas. Terima kasih sudah berbagi sebelum saya salah takaran, semoga kimjang-nya lancar besok.', now() - interval '5324 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900131, 900005, '00000000-0000-4000-9000-000000000026', 17, 'Bes, salamat sa post na ''to — ako mismo ang nangungulit sa dormmates ko tungkol sa flu shot 😄 Sa maliit na klinik malapit sa plant namin sa Ansan, ARC at NHIS card lang dalhin, walang reservation, mga 15 minuto at hindi kalakihan ang bayad — dumating ako mga 9am at walang pila. Masakit lang ang braso isang gabi tapos okay na, sulit na sulit. Saka friendly reminder: huwag mag-iskedyul ng kahit anong Thursday morning dahil suneung — noong isang taon naipit ako sa traffic sa may testing site, grabe, hulas ako sa bus. Go na kayo bago pa lumala ang lamig, bes! 💉❄️', now() - interval '5354 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900132, 900015, '00000000-0000-4000-9000-000000000017', 8, 'Aka, juda o''rinli patch notes — bizning eski yotoqxona ham xuddi shu turdagi pul yeyuvchi. O''tgan qishdan tajriba: boiler kuniga ikki marta 예약 rejimida, eshikka rulonlangan sochiq, va kimjang uchun tizzaga yostiqcha (무릎패드) albatta oling, o''tgan yili tizzam oyog''imdan ko''proq og''rigan edi. Payshanba ertalab Gimpo shiftimga boradigan avtobus ham sinov hududi atrofidan chetlab o''tishi mumkin — yo''lni kechqurun tekshirish maslahatingizni esda tutaman. Shanba kuni kimjang bizda ham, umurlarimizga omad! 😊', now() - interval '5364 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900133, 900015, '00000000-0000-4000-9000-000000000030', 9, 'Тайлбар яг байлаа, надад хамгийн их хэрэгтэй байсан зүйл бол авто зогсоох таймер гэдэг нь. Би чинь энэ бямба гарагийн өглөө вакцин хийлгээд, өдөр нь ажлын хамт кимжангаа хийх гэж байгаа учир хөнжлөө дараа зах дээрээс хайна. Худалдаж авахдаа таймерын товчоо шууд дарж үзээд, KC тэмдэгтэйг сонгоно. 8:40 орчим галт тэрэг богино хугацаанд зогсдогийг анх сонслоо, ээлжиндээ явах цагаа урьдчилан тооцоолох болно. Кимжангийн дараа арай амжилттай байгаарай.', now() - interval '5317 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900134, 900019, '00000000-0000-4000-9000-000000000030', 3, '2+1 урилгаа үнэхээр хэмнэлттэй байж. Би ч 11/11-нд ажлын шугамынхаа хамт олонд Pepero тараасан, хамгийн их талархсан нь өглөөний ээлжийнхэн байсан санагдана. Кимжанд Инчоноос очих боломжгүй ч сэтгэлээсээ дэмжиж байна. Гарын хувьд дээрх постуудаас уншсанаар резинэн бээлийнхэн доор нимгэн хөвөн бээлий өмсөх нь хамгийн дүнтэй зөвлөгөө мэт байна.', now() - interval '5329 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900135, 900016, '00000000-0000-4000-9000-000000000014', 1, 'Your routine is honestly almost identical to mine and it works. On top of the mask-on-subway and 20-second handwashing, I''ve found wearing a thin scarf over my nose and mouth on the walk between the subway and the academy makes a real difference — that cold air is what usually triggers it for me. I keep cough drops in my bag for my students and coworkers all winter, and I''d add: get the flu shot now, because the first sniffle in a hagwon classroom travels through the whole building by Friday. :)', now() - interval '5196 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900136, 900015, '00000000-0000-4000-9000-000000000015', 10, 'Okay, saving this whole post, y''all — I''ve been hunting an electric blanket all week and I 100% would have grabbed the cheapest one without checking for an auto-off timer, so that tip is gold. I''ve had my eye on the stalls around Songtan shopping street where they''re usually under 30,000 won, and I love your trick of testing the plug and timer button before you pay, because you know they''re not taking it back 😅 Bubble wrap on the windows and a towel under the door got us through last winter in our drafty villa, so I can second those too. The suneung note hit home — my Korean tutor''s students are testing Thursday and I''m quietly rooting for them like they''re my own, so I''m keeping my errands off the roads that morning. And kimjang — mine''s Sunday with the spouses'' club, my first ever, so the knee pad advice is going straight on my packing list. Hope your back survives Saturday, pray for mine! 🙏❄️🥬', now() - interval '5157 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900137, 900017, '00000000-0000-4000-9000-000000000004', 5, '매년 수능 날엔 저희 동네 버스도 시험장 옆 학교 때문에 아침부터 우회해서 등하원 시간 계산이 잘 안 되더라고요. 회의를 오후로 옮길 수 있으면 그게 제일 확실하고, 아침에 가야 한다면 지하철로 8시 반 전에 도착해서 근처 카페에서 천천히 기다리시는 걸 권해요. 청각평가 시간인 8시 40분쯤 지하철이 잠깐 멈추니 그 전에 내려 계셔야 해요. 저희 아이 학원도 목요일 수업만 오후로 미뤘는데, 수험생 여러분 모두 좋은 결과 있길 응원합니다.', now() - interval '5062 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900138, 900013, '00000000-0000-4000-9000-000000000033', 7, 'កុំភ័យណាបង រដូវរងាដំបូងរបស់អូនក៏ភ័យដូចគ្នាដែរ 😊 អូនដាក់ប៊ូយឡា (boiler) ឲ្យស្ថិតក្នុងម៉ូដចេញផ្ទះ (외출) ពេលចេញទៅរៀន ហើយភួយអគ្គិសនីបើក ៣០ នាទីមុនគេង រួចបិទវិញ ថ្លៃឧស្ម័នមិនឡើងខ្លាំងទេ។ ដាក់ត្រដាសចាស់មួយដុំក្រោមទ្វារ និងស្រទាប់ផ្លាស្ទិកលើបង្អួច ជួយទប់ខ្យល់ត្រជាក់បានខ្លាំងណាស់ ចំណាយតិចពិតៗ។ ចំណែកឯការចាក់វ៉ាក់សាំងគ្រុនចាប់ត្រូវយក ARC និងប័ណ្ណ NHIS ទៅព្រឹកមុន ១០ ម៉ោង អូនចាក់រួចហើយ ត្រឹម ១៥ នាទីក៏រួចដែរ 🙏 ភួយអគ្គិសនីរបស់បងរកបានហើយឬនៅ?', now() - interval '5086 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900139, 900017, '00000000-0000-4000-9000-000000000023', 6, 'Saya setuju dengan teman di atas, pindahkan rapat ke siang, itu paling aman 😄 Dari pengalaman enam tahun sini, setiap hari suneung jalan dekat sekolah ditutup mulai pagi, bus memutar, dan taksi di dekat lokasi ujian hampir mustahil dapat. Kalau memang harus pagi, sarapan dulu di kafe dekat kantor klien sambil tunggu jam 10, jalan terasa santai. Jumat pagi biasanya sudah kembali normal, tinggal bagikan sisa Pepero-nya saja.', now() - interval '4959 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900140, 900020, '00000000-0000-4000-9000-000000000003', 1, '第一次就把装备准备得这么齐全，你已经赢一半了，加油！我上周跟韩国同事腌的实战经验：橡胶手套里面再套一双薄棉手套，不然咸白菜冰得手指很快没知觉；慢也完全没关系，阿嬷们会直接上手帮你摆正手法，一边纠正一边继续聊家常，特别亲切。Pepero 给志愿者这个主意满分，绝对瞬间成为全场团宠 🍫 周六快乐，回来记得晒你的 kimchi 战利品 🍲', now() - interval '4988 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900141, 900017, '00000000-0000-4000-9000-000000000041', 7, 'Same situation here — I pushed my Thursday start to 10:00 and I''m leaving home after 9:10, once the 8:40 listening-test pause (subway trains briefly stop) and the school-zone traffic control have passed. If the meeting really can''t move, subway only and arrive before 8:30 or after 9:15; buses reroute around test sites from ~7am and taxis near schools are basically a lottery. Afternoon is still the safest option if the client agrees, but if not, build in the buffer and sit in a café near their office — beats a stressed squeeze.', now() - interval '4991 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900142, 900017, '00000000-0000-4000-9000-000000000017', 8, 'Aka, menga ham o''tgan yilida aynan shu bo''lgan — payshanba ertalab Gimposhdagi fabrikaga boradigan marshrutka sinov maktabi atrofidan chetlab o''tib, bemalol 40 daqiqa kechikdim, shu kundan keyin esa uni navbatga qo''ymayman. Eng osoni uchrashuvni tushdan keyinga surish; bo''lmasa metroda 8 dan oldin chiqib, 8:40 dagi listening uchun poyezd to''xtashidan avval manzilga yetib boring. Taksi o''yinboshi — do''stim o''tgan yili maktab qarshisida yarim soat kutib turgan edi.', now() - interval '4926 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900143, 900007, '00000000-0000-4000-9000-000000000045', 4, 'Posting in English since my Khmer is nonexistent and my Korean is barely better, eh 😅 Kimjang solidarity — my co-teacher invited me to her family''s this Saturday too, and I''ve been quietly terrified of chopping the baechu wrong in front of her halmoni. Everyone who''s been swears the ajummas just reach over and fix your hands mid-chop, nobody grades you, and gestures plus smiles carry you through the Korean part. Bring thin cotton gloves under the long rubber ones (cold salt is brutal on your hands) and a knee pad or folded towel — hwaiting to us both! 🍁', now() - interval '4945 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900144, 900021, '00000000-0000-4000-9000-000000000031', 1, '공동김장 처음 신청하셨다니 참 잘하셨어요, 저도 이번에 가게 사장 노릇 하고 나서 처음 이웃이랑 김장하러 가요 😊 절임배추 절이는 건 어른들한테 배우는 게 최고예요, 소금 간은 손으로 비벼봐야 알더라고요. 무릎패드는 꼭 챙기시고, 고무장갑 안에 얇은 면장갑 한 겹 더 끼우면 소금물이 시려도 훨씬 낫습니다. 일요일 무사히 다녀오시고, 김치 몇 통 인증 기다릴게요 🍲', now() - interval '4794 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900145, 900004, '00000000-0000-4000-9000-000000000021', 28, 'Honestly same, my drafty one-room turned into a fridge the first night of the cold snap and I''m scared to even open the bill 😂 What actually saved me: electric blanket on a 30-minute timer before bed then off, a hot water bottle under the covers, and bubble wrap plus a rolled towel under the door — no joke, the room holds heat so much better now. I just call the November bill tuition for surviving winter and promise myself December will behave 🥶❄️', now() - interval '4708 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900146, 900015, '00000000-0000-4000-9000-000000000013', 11, 'Front desk in Busan here and this is basically the checklist my manager has been double-checking all week lol 😅 We''re already warning Thursday arrivals that taxis near test sites are impossible to catch in the morning and our airport shuttle is pushed back for the 8:40 listening pause, so booking a pre-arranged pickup or checking in after 10 is the move. Also confirming the auto-off timer tip on the electric blanket — my gas bill and I are both grateful 🙏 Kimjang with my coworkers Saturday too, may our backs survive sis!', now() - interval '4791 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900147, 900003, '00000000-0000-4000-9000-000000000016', 3, '동묘 장악력이 대단하시네요. 다만 저가 패딩은 사기 전에 지퍼를 몇 번 끌어보고 솜 두께를 꾹꾹 눌러보세요. 제가 몇 년 전 만 원짜리를 샀다가 지퍼가 한 시즌 만에 말라서 겨울 중간에 다시 샀습니다. 전기요 30분 후 끄기와 페페로 나눠먹기는 진리, 11/11 맞아서 클래스메이트들한테 잘 전해주세요.', now() - interval '4626 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900148, 900005, '00000000-0000-4000-9000-000000000001', 6, '回答楼上韩语的问题：「독감 예방접종 하러 왔어요」这句完全自然，前台一听就懂；说「왔는데요」结尾会更委婉一点，两个都常用。我11月初打的时候流程是：出示ARC和NHIS卡，填一张简单的单子（是否第一次接种、有无过敏史），全程十几分钟。另外提醒一下，不是所有校医院都能现场挂号，有的要提前在官网预约，你既然约好了就按时间过去，上午10点前确实人最少。', now() - interval '4648 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900149, 900006, '00000000-0000-4000-9000-000000000012', 0, 'มาเชียร์จากคนไทยแถวซินชนค่ะ จากประสบการณ์ห้องเดียวของฉัน ตอนออกไปเรียนอย่าปิดบอยเลอร์ทิ้งเฉยๆ ให้ตั้งโหมดเวชุลไว้กลับมาแล้วตั้งยันเอ 20 องศาจะประหยัดกว่าปิดแล้วเปิดใหม่ค่ะ 🥶 ผ้าห่มไฟฟ้าเปิด 30 นาทีก่อนนอนแล้วปิด ใส่ถุงเท้าหนาๆ แล้วไปไดโซ่ซื้อฟิล์มบับเบิลแรปติดหน้าต่าง อุ่นขึ้นเดแบคเลย ส่วนเปเปโร่ก็น่ารักมาก โต๊ะฉันยังมีภูเขาช็อกโกแลตตั้งแต่วันที่ 11 ยังแกะไม่หมดเลย 555 เชียร์น้องสุเนิงพฤหัสนี้ด้วยนะคะ 🍫', now() - interval '4675 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900150, 900020, '00000000-0000-4000-9000-000000000012', 2, 'โชคดีนะคะกับคิมจังแรก 555 เคล็ดลับที่ใช้เองคือใส่ถุงมือผ้าบางๆ ไว้ใต้ถุงยางยาว กะหล่ำเค็มเย็นๆ ทำให้มือแข็งเร็วมากค่ะ 🥶 แล้วหิ้วถุงใบใหญ่ไปด้วยเลยนะคะ เพราะอาจุมม่าชอบให้คนมาช่วยหอบคิมจีกลับบ้านเสมอ ถือเป็นบุญ 555 ส่วนกล่องเปเปโร่ไปแจกอาสาสมัครนี่เทพมาก ทีมฉันเห็นก็รักทันที แต่โต๊ะฉันตอนนี้ก็ยังมีภูเขาช็อกโกแลตค้างอยู่เหมือนกัน ต้องค่อยๆ แกะไปเรื่อยๆ 555 🍫', now() - interval '4668 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900151, 900018, '00000000-0000-4000-9000-000000000025', 4, 'That ratio is right boss, I do kimjang with the ajummas at my port every year — for 10 heads they use about 2.5kg of coarse salt, packed tight between the thick stems and flipped once after six hours. If a thick stem bends without snapping, it is ready to rinse. And yes, buy your own thick rubber gloves, the shared ones always leak. 👍', now() - interval '4542 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900152, 900016, '00000000-0000-4000-9000-000000000023', 2, 'Saya masih belum sempat cek flu musim ini, tapi mulai minggu lalu saya juga sudah terbiasa, antre wajib di boiler room selagi menunggu sembuh. Di dalam kedai ramen sepanjang jalan pulang, kini kumpulan obat batuk dan vitamin di tas kecil telah jadi tontonan menarik. Saya bisa memberi rekomendasi 3 jenis jus vitamin di convenience store yang mengeluarkan tangki dengan pembelian. Belum, saat ini awetnya lumayan 👍', now() - interval '4483 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900153, 900013, '00000000-0000-4000-9000-000000000009', 8, 'Đừng lo quá bạn ơi, ký túc xá cũ của mình ở Daegu cũng y hệt, mùa đông nào cũng sợ hóa đơn gas 😅 Cách mình làm: ra ngoài thì chỉnh boiler sang chế độ 외출, trước khi ngủ bật chăn điện 30 phút rồi tắt, phòng giữ được ấm mà hóa đơn gần như không tăng. Ở Daiso bán màng bong bóng dán cửa sổ mấy nghìn won thôi, khe cửa nhét khăn cuộn lại, dưới chăn thêm bình nước nóng là ngủ qua đêm đủ ấm. À bạn tiêm cúm sớm sớm nha, buổi sáng phòng khám ít người xếp hàng lắm, 15 phút là xong 🥶', now() - interval '4554 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900154, 900019, '00000000-0000-4000-9000-000000000017', 4, 'Uka, bu mening birinchi Pepero Day-im ham: ishxona yonidagi do''kondan 2+1 aksiyada bir nechta quti olib tungi smenaga taqsimladim, hammamiz yaxshi kayfiyatda bo''ldik. Gaz hisobi bo''yicha sizni tushunaman — bizning eski yotoqxona ham xuddi shunday, lekin 외출 rejimi va elektr ko''rpani 30 daqiqa yoqib o''chirish raqamni saqlab qoldi. Shanba kuni Gimpo''da koreys hamkasblar bilan kimjangimiz bor, Hwaseongga yetib bora olmayman — lekin rezina qo''lqop ostiga yupqa paxta qo''lqop kiying, sovunli karam qo''lni juda tez muzlatadi. 😊', now() - interval '4507 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900155, 900018, '00000000-0000-4000-9000-000000000002', 5, '비율 정확합니다 👍 저희도 10포기에 고운소금 2.5kg쯤, 굵은소금이면 조금 여유 있게 잡으세요. 배추 밑동을 칼로 십자로 살짝만 갈라주면 소금이 훨씬 잘 들어가고, 절임 배추 눌러봤을 때 힘줄 부러지지 않고 부드럽게 꺾이면 절임 끝입니다. 헹굴 땐 세 번만 씻으세요, 네 번 씻으면 간이 떨어집니다. 염도는 어머님들 손맛이 곧 계량기예요, 다음 김장은 실패할 게 없습니다.', now() - interval '4425 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900156, 900002, '00000000-0000-4000-9000-000000000012', 5, 'ใส่แพดเดดโค้ตขึ้นรถไฟฟ้าไปเลยค่ะ แล้วยัดเบลเซอร์ลงกระเป๋าโทท ไปเปลี่ยนที่ห้องน้ำสถานีหรือคาเฟ่ใกล้ออฟฟิศ คนเกาหลีก็ทำกันหมดแบบนี้ ไม่มีใครว่าอะไรหรอก 555 ส่วนเซลฟ์อินโทรอย่าแก้ราตรีๆ แล้วค่ะ เอามาจำเป็นสามประโยคแล้วพูดออกเสียงดังๆ บนรถไฟดีกว่า ขอให้สัมภาษณ์ผ่านฉลุยนะคะ ปล. เปเปโร่เก็บไว้กินเองเถอะค่ะ โต๊ะฉันยังมีภูเขาช็อกโกแลตค้างอยู่เลย 555 🍫🥶', now() - interval '4330 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900157, 900021, '00000000-0000-4000-9000-000000000041', 2, 'First kimjang for me too — this Saturday with my team, so I''m collecting notes the same way. What I have so far matches the comment above: your own rubber gloves in your actual size because the shared ones leak paste, thin cotton gloves underneath since cold salted cabbage numbs your hands fast, plus a knee pad and clothes that go straight into the wash. Curious about the apartment version though — do residents who join actually get to take some kimchi home, or does everything go into the building''s shared stores? Either way, learning the salting from the elders in your own building sounds like a decent return on a Sunday.', now() - interval '4395 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900158, 900004, '00000000-0000-4000-9000-000000000040', 29, '「Anyone else in an older villa have real tricks, or is this just the November tax?」の質問にお答えします。大田で古いビラに4年住んでいますが、ボイラーは完全に切らず、外出中は외출モード、夜は예약で20度、寝る30分前だけ電気毛布をつけて切る組み合わせが一番効きました。それから、検針票の사용량(㎥)を表計算に記録して昨年の同月と比べる癖をつけてから、どの週に使いすぎたか一目で分かるようになり、無駄遣いが減りました。11月は誰にとっても一種の「税」だと思うので、12月の請求書に向けて一緒に頑張りましょう。', now() - interval '4421 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900159, 900020, '00000000-0000-4000-9000-000000000013', 3, 'Sis, same boat — my Korean coworkers are dragging me into my first kimjang this Saturday too and I''ve already warned them my chopping skills are front-desk level, not ajumma level lol 😅 My manager-noona told me to wear thin cotton gloves under the rubber ones because the salted cabbage freezes your hands way faster than you''d expect, and to bring an extra-large bag since they always send you home with more kimchi than you can carry. Bringing Pepero for my team as well, 11/11 was made for us 🍫 Fighting, let''s both survive without crying over the cabbage!', now() - interval '4274 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900160, 900015, '00000000-0000-4000-9000-000000000021', 12, 'As a computer engineering student I have to say this is the most readable thing I''ve seen all week — gas bill content written like release notes, honestly legendary 😂 I can confirm the auto-off timer is the real spec, I was checking that exact button at the market stalls this week before buying. No joke, the suneung note is gold too, watching the whole city pause around 8:40 for the listening section still gives me goosebumps every year. My first kimjang is also this Saturday, so let''s pray for both our backs 🙏❄️', now() - interval '4303 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900161, 900016, '00000000-0000-4000-9000-000000000044', 3, 'Most of my habits are for the early mornings — scarf over my nose and mouth on the walk to the bakery until the ovens warm the kitchen, and dry socks waiting at work, because wet commute shoes are how I always caught a cold. A thermos of hot tea at my station does more for me than any vitamin drink. And I got my flu shot last week before the weekend rush, best November decision 🥐', now() - interval '4267 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900162, 900004, '00000000-0000-4000-9000-000000000017', 30, 'Aka, bizning Gimpo yotoqxona ham aynan shunday — eski boiler bilan noyabr hisobi o''tgan yili ikki barobar chiqqan edi. Nima yordam berdi: boiler tunda 예약 rejimida faqat ertalab va kechqurun ishlaydi, eshik ostiga rulonlangan sochiq, yostiq ostiga issiq suv idishi — tun bo''yi isitishni umuman yoqmayman, gaz hisobi shu tufayli oyiga 15 ming won atrofida kamaydi. Yana bittasi: xona sekin issiqsa boiler suv bosimini tekshirib 1.5 baracha to''ldiring — past bosimda u uzoq ishlab kam isitadi, bu eski uylardagi yashirin pul yeyuvchi. Noyabr solig''i hamma uchun, dekabrda engillashtiradi 😊', now() - interval '3884 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900163, 900016, '00000000-0000-4000-9000-000000000026', 4, 'Bes, kapit lang — ang sakit naman ng balita tungkol sa mommy mo, mahigpit na yakap at sana maging maayos ang simula ng dialysis niya 🤍 Ako, dahil linya rin ako sa plant, ito ang routine ko tuwing taglamig: flu shot agad (ARC + NHIS card lang dalhin, mga 15 minuto sa maliit na klinik, at sa 보건소 minsan mas mura o libre pa — dumating ako bago alas-dose para walang pila), scarf sa ilong at bibig pag lalabas kasi ang malamig na hangin ang unang sumasalakay sa akin, tapos 20-secong hugas ng kamay pagdating sa dorm. Electric blanket 30 minutes bago matulog tapos i-off agad para hindi lumipad ang gas bill namin sa dorm. Sana all nga pala may 11/11 Pepero exchange — buhay pa rin ang pusong bata ko 😄 Ingat lagi kayo ng mommy mo, bes! ❄️', now() - interval '3879 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900164, 900021, '00000000-0000-4000-9000-000000000019', 0, '아직 일요일이 앞이라 제가 직접 확인은 못했어요. 다만 공고에 참가 가구끼리 완성 김치를 나눠 간다고 적혀 있고, 작년에 참여했다는 이웃 반장님 말로는 가구당 통 하나씩 받아가고 남은 건 단지 어르신들에게 나눈다고 하셨어요. 일요일에 다녀와서 제대로 확인하고 다시 알려드릴게요 ^^', now() - interval '3753 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900165, 900022, '00000000-0000-4000-9000-000000000045', 1, 'Congrats on surviving the first one, eh 🍁 Mine with my co-teacher''s family is this coming Saturday and I''m still nervous about chopping the baechu wrong in front of her halmoni — it helps so much to hear the ajummas just fix your hands mid-chop instead of grading you. Taking notes from the whole thread: cotton gloves under the rubber ones, a knee pad, and apparently there''s always kimchi to take home. Quick question from one first-timer to another — did the class teachers walk you through the salting step by step, or was it more jump in and copy the person beside you? And thank you for confirming the leave-the-tub-out-a-day-before-the-fridge thing, noting that for sure 😅', now() - interval '3794 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900166, 900010, '00000000-0000-4000-9000-000000000028', 5, 'Pepero survivor solidarity! Grabe, our gift shop sold out of Pepero by mid-morning on 11/11 and I spent the rest of the day redirecting sad guests to the convenience store next door 😂 A Seongsu pop-up day is literally my December dream — I''m saving up for one weekend trip up from Jeju, so please report back which ones are worth the queue, especially any with dessert counters! One tip from my planning so far: book the flight and any pop-up reservations early, December weekends fill up fast 🍂🥶', now() - interval '3616 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900167, 900014, '00000000-0000-4000-9000-000000000034', 2, 'Ой, привет, землячка по обстоятельствам — я из Казахстана и сама всегда читаю состав, так что вопрос понимаю отлично! 😄 Кстати, имей в виду: у Pepero часть вкусов с желатином, я на 11/11 дарила коробки своей группе, так что этикетки — наши лучшие друзья. Сонсу для меня тоже пока белое пятно, но я как раз собираюсь туда на рождественские поп-апы в эти выходные — если найду что-то подходящее по десертам и горячим напиткам, напишу тебе первой, давай сделаем совместный отчёт!! 🎄 А у Seoul Forest я пару раз видела турецкий кебаб, народ мимо него мимо не проходит — проверишь за всех нас 😄', now() - interval '3683 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900168, 900010, '00000000-0000-4000-9000-000000000023', 6, 'Pepero Day di yard kami juga rame, kotak kecil untuk banjang di line saya terima sambil senyum lalu langsung disimpan di saku jaketnya 😄 Saya baru tahu nama tekniknya lamination, jadi nambah pengetahuan dari post ini. Semoga hari liburnya tepat sasaran, daun musim gugur tinggal sisa dikit di sini jadi kalau mau kejar masih sempat.', now() - interval '3570 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900169, 900014, '00000000-0000-4000-9000-000000000026', 3, 'Bes, sabay pala tayo — rest day ko this weekend punta rin ako ng Christmas pop-up sa Seongsu, first time ko! Advice: umaga pa lang pumunta kasi grabe ang pila pagkatapos ng tanghali, at magdala ng hot packs (핫팩) galing Daiso kasi ang lamig sa labas 😄 I-check mo rin ang 젤라틴 (gelatin) at 알코올 sa syrups ng mga dessert stalls — marami daw nagtatago doon sa festive drinks. Kung South Asian ang hanap mo, talagang sa Itaewon ang maraming choice, tatlong istasyon lang pagtawid ng ilog — report ko sa''yo kung anong mapapasamahan ko para sa map mo, fighting sa finals! 🎄', now() - interval '3586 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900170, 900016, '00000000-0000-4000-9000-000000000027', 5, 'My Monday flu shot was honestly the best thing I did this week too — arm sore for one night only, grabe, worth it before the real cold settles in. My small habits from five winters here: mask on the subway like you said, a thermos of warm tea in my bag when I go out to teach, dry thick socks waiting at home, and the electric blanket on a 30-minute timer before bed then off (our old ondol and my gas bill both thank me). I also carry cough drops to hand out in class all winter — one sniffle in a room full of students and the whole academy catches it by Friday, saka another teacher''s tip above about a thin scarf over your nose on the walk is a real one. Praying your dialysis start goes smoothly and gently — please update us how it goes, okay? 🤍❄️', now() - interval '3366 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900171, 900016, '00000000-0000-4000-9000-000000000004', 6, '투석 시작을 앞두고 몸이 많이 신경 쓰이시겠어요, 작은 습관부터 차근차근 지키시면 좋아요. 저희 집은 외출에서 돌아오면 가족 모두 20초씩 꼼꼼히 손을 씻고, 밖에서는 얇은 머플러를 코와 입에 걸쳐 차가운 공기가 기관지를 직접 자극하지 않게 해요. 독감 주사는 지난주에 동네 가정의원에서 맞았는데, 외국인등록증과 건강보험증만 있으면 예약 없이 15분이면 끝나니 미루지 마시고 꼭 챙기세요. 병원 다니시는 일 잘 되길 진심으로 응원합니다.', now() - interval '3380 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900172, 900023, '00000000-0000-4000-9000-000000000018', 1, 'Как здорово, что у вас такой сплочённый кампус — из одной комнаты в Сеуле всегда завидую общежитиям, где все вместе! 😄 Если жара встаёт редко, бумага и жидкие горячие пакеты (хотпэк) из Дайсо за копейки спасают лучше всяких обогревателей, а электрическое одеяло на таймере за 30 минут до сна — вообще палочка-выручалочка, газ почти не трогаем. А 14 корзин кимчи — это уже уровень! Моя группа собирается в субботу, так что если что-то важно из гайдлайна не учли — напишите, я сразу предупрежу своих, они тоже новички 🙈 Держитесь в эти два дня, и пусть у вашей девушки на кимджанге всё получится, обнимаю 🧡', now() - interval '3281 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900173, 900021, '00000000-0000-4000-9000-000000000021', 3, 'Honestly, learning the salting from the elders in your own building sounds like the best possible first kimjang 🥬 I''m doing my first volunteer kimjang this Saturday and I''ve packed basically the same kit — rubber gloves in my actual size, a knee pad, and clothes that go straight into the wash. And no joke, respect for pushing your deliveries past 10 on suneung day — the sky over my campus went completely silent for the listening test and it gave me goosebumps 😂', now() - interval '3325 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900174, 900007, '00000000-0000-4000-9000-000000000029', 5, 'Би өнгөрсөн бямба гарагт найзынхаа гэр бүлийн кимжанд орж төгссөн дөнгөж 😊 Хэл ойлгохгүй байх нь асуудал биш — нэг ажумма гараа өвөрт барьж дунд нь засаад "үргэлжлүүл" гэдэг, ангилах гэж хүн байдаггүй. Резинэн бээлийний доор нимгэн хөвөн бээлий өмсөөрэй, нэрмэл байцаа хүйтэн учраас гар хүргэлгүй тэсвэрлэхэд их тусалдаг. Гэрийнхэнд хийлгэсэн кимчинь аваачиж март, энэ мөчир өвлийн хамгийн сайн бэлэг шүү 🍂', now() - interval '3282 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900175, 900007, '00000000-0000-4000-9000-000000000019', 6, '한국어 못한다고 전혀 걱정하지 않으셔도 돼요, 김장터에서는 인사말과 절차가 반 이상입니다. 저는 아직 절임배추 손놀림도 어색하지만 일요일 공동김장에 나갈 계획이에요, 어르신들이 손 잡고 바로잡아주시니 실수해도 아무도 평가하지 않습니다. 고무장갑 안에 얇은 면장갑을 먼저 끼우고, 무릎패드와 갈아입을 상의를 꼭 챙기세요. 화이팅, 김치 몇 통은 꼭 챙겨 오세요.', now() - interval '3148 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900176, 900017, '00000000-0000-4000-9000-000000000001', 9, '去年修能当天我也赶过早上的安排，经验是：地铁最稳，但一定要在8点40分听力测试前下车，那几分钟全线暂停，别卡在隧道里；考场周边的公交从早上7点开始绕行，学校附近出租车基本叫不到。所以能挪下午就挪下午，最省心；实在挪不动就坐地铁8点半前到，在客户公司附近的咖啡馆等，比赌路上时间靠谱。前一年年底也是这么过来的，周四上午全首尔都在给考生让路，客户多半也理解。', now() - interval '3151 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900177, 900003, '00000000-0000-4000-9000-000000000041', 4, 'Same Dongmyo route my first winter — the padded coat I got there is still going three seasons later. Checklist before you pay: zip and unzip it fully a few times (zippers die first on cheap ones), squeeze the padding for clumping, hold it up to the light for thin spots, and smell the collar — mothball or mold smell never really washes out. Hold it against a jacket you already own for shoulder width, then budget one wash before wearing, used outerwear usually needs it.', now() - interval '3216 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900178, 900013, '00000000-0000-4000-9000-000000000025', 9, 'For the person asking about the public health center: I do mine at the Gun Bogunso near my place in Busan, no appointment, just walk in with ARC and NHIS card in the morning, it took about 15 minutes and was around 20,000 won. Go before 10am while it is quiet, no problem. And for the bill, my ondol room is weak too — set the boiler on 예약 so it stops after you sleep, hot water bottle under the covers, and an electric blanket 30 minutes on a timer, my room held up fine last winter. 👍', now() - interval '3085 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900179, 900018, '00000000-0000-4000-9000-000000000032', 6, 'អរគុណណាស់ ចំណាំនេះមកដល់ពេលល្អណាស់ ព្រោះថ្ងៃអាទិត្យនេះខ្ញុំនឹងធ្វើគីមជាំងជាលើកដំបូងជាមួយគ្រួសារចៅហ្វាយផង។ តាមមតិខាងលើ ពាក្យ 염도 មានន័យថាកម្រិតជាតិប្រៃនៃទឹក ប្រហែល ២-៣% ពេលប្រៃស៊ាង ដូច្នេះខ្ញុំនឹងសម្គាល់មើលមាតាចៅហ្វាយធ្វើយ៉ាងណាដែរ ហើយបើដងធំអាចបត់បានដោយមិនបែក នោះប្រៃស៊ាងចប់ហើយ។ ខ្ញុំបានរៀបចំស្រោមដៃកៅស៊ូក្រាស់សមនឹងដៃ ខ្នើយជង្គង់ និងស្រោមដៃក្រណាត់ស្តើងសម្រាប់ពាក់ខាងក្រោមរួចហើយ 🙏', now() - interval '3096 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900180, 900022, '00000000-0000-4000-9000-000000000017', 2, 'Uka, birinchi kimjang bilan tabriklayman — o''tgan yili men ham tungi smenadan keyin ko''proq charchagandim 😊 Tajribamdan: rezina qo''lqop ostiga yupqa paxta qo''lqop kiying, salqin sho''r karam qo''lni juda tez muzlatadi. Kilga yostiqcha ham shart, chunki ertasi kuni tizim oyog''imdan ko''proq og''riydi. Kimjangni kimchi bir kun xona haroratida turib, keyin muzlatgichga qo''yilishi haqidagi maslahat to''g''ri — jiznimi shu tartibda saqlayapman. Yana kimjang qilsa o''zingizni bezovta qilmang, ajummalar doim qo''lingizni ko''rsatib turadi.', now() - interval '2936 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900181, 900015, '00000000-0000-4000-9000-000000000025', 13, 'Confirming the timer tip boss — test the plug and timer button in the stall before you pay, mine was under 30,000 won at the home-goods row in Bujeon market and the auto-off is the part that matters. On Thursday the port trucks get held at the school-zone control after 7am too, so pushing your meeting to the afternoon is the safe call. Good luck with kimjang, the winter flatfish run starts this weekend so my Saturday will be busy anyway. 👍', now() - interval '2883 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900182, 900020, '00000000-0000-4000-9000-000000000014', 4, 'Sending luck — your kit is already better than what I brought to my first market trip, honestly. Two things I''d add from everything I''ve collected: thin cotton gloves under the rubber ones, because the salted cabbage chills your hands way faster than you''d expect, and if the ajummas send you home with kimchi, let the tub sit at room temperature for about a day before it goes in the fridge, it tastes so much better. My first kimjang with my landlady''s family is this weekend too, so let''s both survive the backache. :)', now() - interval '2888 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900183, 900018, '00000000-0000-4000-9000-000000000044', 7, 'Saving this, thank you — the ratio matches what my Korean coworkers used at the shared kimjang last year. From the pastry side I can confirm the science: salting works exactly like macerating fruit for a tart filling, drawing water out evenly so the seasoning goes in deep, so don''t rush the six hours 🥐', now() - interval '2995 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900184, 900018, '00000000-0000-4000-9000-000000000038', 8, '初めての김장がこの週末にあるので、白菜10枚に粗塩2.5kgという割合をさっそくノートに書き込みました。「염도」が塩分濃度のことだと初めて知れて、韓国語の勉強にもなりました。切った白菜は3回だけ洗えばいいというコツもコメント欄で見つけたので、一緒にメモしておきました。明日の김장、どうぞ頑張ってください ❄️', now() - interval '2993 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900185, 900014, '00000000-0000-4000-9000-000000000013', 4, 'Adding the Busan side of the map, sis! The cluster of halal spots right near Busan Station in Choryang — kebab and South Asian food all within a 10-minute walk — is where my coworkers and I end up after late shifts, so if any of your classmates ever come down to Busan, send them there. Also seconding the gelatin warning, festive desserts love hiding it 🍫 Fighting on your finals!', now() - interval '2846 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900186, 900007, '00000000-0000-4000-9000-000000000028', 7, 'Bes, don''t stress about the Korean at all — at my first dorm kimjang I survived on smiles, gestures and "네!" and the ajummas still adopted me by lunch 😂 Wear thin cotton gloves under the long rubber ones because cold salted cabbage is grabe on your hands, plus a knee pad since you''ll be on the floor a while. If you cut something wrong they''ll just fix your hands mid-chop and say keep going — that''s how they show love, not judgement. And you''re coming home with a tub of kimchi no matter what, so hwaiting tomorrow, it''s the best trade ever 🥶🍂', now() - interval '2826 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900187, 900023, '00000000-0000-4000-9000-000000000042', 2, 'वाह, 11 बच्चियों के साथ किमजाङ — ये तो दिदी समूह बन गया यार! मैं इसी हफ्ते लैब के साथ अपना पहला किमजाङ करके आई न, अब सब मुझे ''किमची दीदी'' बुलाते हैं 😅 बच्चियों को बता देना: अपने हाथ के साइज़ का गोमुजाङगप (रबर दस्ताने) हर एक ज़रूर लाए और अंदर पतला म्योनजाङगप पहने — बेचू के खारे ठंडे पानी में हाथ दस मिनट में सुन जाते हैं। घुटनों के लिए मुरीपैड या जुड़ा पुराना तकिया और वो कपड़े जो सीधे वॉश में चले जाएँ। और टिप: किमची पहली रात कच्ची लगती है, घबराना नहीं — एक दिन शिलोन पर रखकर फिर नेङजाङगो में, तब स्वाद ही अलग आता है।', now() - interval '2801 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900188, 900013, '00000000-0000-4000-9000-000000000026', 10, 'Bes, kapit lang — tao lang talaga tayo sa gas bill tuwing Nobyembre 😅 Ito ang ginagawa namin sa dorm: hindi buong gabi ang boiler, kundi electric blanket 30 minutes bago matulog tapos i-off agad, hot water bottle sa ilalim ng kumot, bubble wrap sa bintana at rolled towel sa ilalim ng pinto (Daiso lang, mga ilang libong won). Sa flu shot, diretso ka na sa Gun Bogunso (보건소) — ARC at NHIS card lang dalhin, walang reservation, 15-20 minuto lang kapag umaga bago alas-10, at mas mura pa kaysa clinic, minsan libre pa. Wag mo nang iliban ''yan bes, bago pa dumami ang tao — ako mismo ang sundo ng buong dorm, hays 😄 Ang swerte mo rin sa kimchi ng landlady mo, tapos na ang winter food prep mo!', now() - interval '2507 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900189, 900024, '00000000-0000-4000-9000-000000000032', 1, 'ថ្ងៃទី ១១ កូនស្រីរបស់ចៅហ្វាយក៏បានផ្ដល់ប្រអប់ប៉េប៉េរូមួយមកខ្ញុំដែរ ខ្ញុំចែកជាមួយសហការីនៅពេលថ្ងៃត្រង់ក្នុងផ្ទះស្មៅ អ្នកទាំងអស់គ្នារីករាយណាស់។ ខ្ញុំក៏ទើបទិញអាវពោងក្រាស់ជាលើកដំបូងដែរ ព្រឹកឡើងទៅកន្លែងធ្វើការកាន់តែងាយស្រួលជាងមុន។ បិទភក់នៅលើកញ្ចក់បង្អួច និងបើកគ្រែអគ្គិសនី ៣០ នាទីមុនគេង គឺជាវិធីដែលខ្ញុំប្រើដូចអ្នកហ្នឹងដែរ វិក្កយបត្រហ្គាសក៏មិនឡើងខ្ពស់ខ្លាំងណាស់ទេ 🙏❄️', now() - interval '2451 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900190, 900013, '00000000-0000-4000-9000-000000000011', 11, 'ขอเสริมเรื่องเตาน้ำมัน (난로) หน่อยนะคะ ถ้าเผาทั้งคืนอย่าปิดห้องสนิท ต้องเปิดหน้าต่างระบาย (환기) ไว้เล็กๆ เพราะก๊าซพิษ 일산화탄소 สะสมตอนเราหลับได้ หนูเฮ็ดโรงเรือนสตรอว์เบอร์รี เจ้าของฟาร์มบังคับให้มีตัวตรวจจับก๊าซไว้ข้างเตาเลย ร้านเครื่องมือหลักพันวอนเอง ปลอดภัยขึ้นเยอะ 🔥 ถ้าเป็นฮีตเตอร์ไฟฟ้าก็ตั้งเวลาให้มันดับเองตอนหลับลึก ส่วนวัคซีนหวัดให้ไปเช้าๆ ก่อน 10 โมง เอา ARC กับบัตรสุขภาพไป 15 นาทีจบ สู้ๆ นะคะ ❄️🍓', now() - interval '2511 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900191, 900024, '00000000-0000-4000-9000-000000000014', 2, 'This sounds exactly like my week at the academy in Gangnam — my students turned break time into a little Pepero exchange too, and I''d been stockpiling boxes from the 2+1 deals for it. For Thursday, I''m pushing my first classes to the afternoon since my bus reroutes around a test site and the students deserve the quiet morning. And I can vouch for the bubble wrap on the windows plus the electric blanket on a 30-minute timer before bed; that combo is what got me through my first Seoul winter without crying at the gas bill. Warm thoughts to you and your students this week. :)', now() - interval '2284 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900192, 900015, '00000000-0000-4000-9000-000000000036', 14, 'Забираю в закладки — читается как внутренний отчёт. Мой главный аргумент за таймер: счёт за прошлый январь. С тех пор электроодеяло на 30 минут до сна, бойлер в 외출, пока я на работе, и ноябрь пока держится в пределах painful, а не catastrophic. В четверг из-за сунына работаю из дома, так что коммьют меня не коснётся, а на субботний кимджанг уже заказала 무릎패드 — судя по комментариям, предмет первой необходимости. По итогам субботы расскажу, выжила ли спина 🥲', now() - interval '2380 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900193, 900008, '00000000-0000-4000-9000-000000000042', 13, 'पहला किमजाङ के लिए शुभकामनाएँ यार! मैं इसी हफ्ते लैब के साथ अपना पहला किमजाङ कर आई न, अब पूरा लैब मुझे ''किमची दीदी'' बुलाता है 😅 सबसे काम की टिप: रबर गोमुजाङगप के अंदर पतला सूती म्योनजाङगप पहनो — नमकीन ठंडा पानी हाथ दस मिनट में सुन देता है, इससे बहुत फर्क पड़ता है। शनिवार सुबह का सुई फिर रविवार किमजाङ ठीक ही है, मेरा हाथ भी सिर्फ एक रात दुखा था। बस घर का डल्लो ज़रूर भरकर आना और किमची एक दिन शिलोन पर रखकर फिर नेङजाङगो में डालना — तब स्वाद ही अलग आता है।', now() - interval '2250 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900194, 900014, '00000000-0000-4000-9000-000000000024', 0, 'Gais kalian tuh terbaik, gue speechless 😭🙏 Yang weekend ini ke Seongsu, gaskeun — ayo laporan bareng, nanti gue rangkum jadi satu post biar adik-adik baru tinggal scroll aja! 😆 Tips-nya langsung gue jalanin: dateng pagi-pagi sebelum antreannya gila, dan hotpack Daiso udah nangkring di tas buat perang dingin (mantel Jakarta gue bahaya banget buat standby lama 🥲). Cluster halal deket Busan Station di Choryang langsung gue caplok ke sisi Busan peta — nanti gue update lagi kalau ada temen lab yang liburan turun ke sana. Dan Pepero itu beneran jebakan gelatin, makanya gue baca label pake kacamata plus lampu sorot hahaha. Doain peta Seongsu akhirnya ada isinya sebelum finals menelan gue utuh ya! 🍫✨', now() - interval '2233 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900195, 900018, '00000000-0000-4000-9000-000000000029', 9, 'Харьцааг баталж байна — өнгөрсөн бямба найзынхаа гэр бүлийн кимжанд орсон, тэд ч мөн л арван толгой байцанд 2.5 кг том ширхэгт давс ашигласан 😊 Зургаан цагийн дараа зузаан ишээ нугалахад хагарахгүй, зөөлөн байвал угаах цаг нь болсон гэдгийг тэнд ажигласан. Нэг зүйл нэмье: резинэн бээлийний доор нимгэн хөвөн бээлий өмсөөрэй — нэрмэл байцаа гар хүргэлгүй болгодог, өвдөгний дэвсгэрээ мартаж болохгүй. Давсалсан байцаагаа гурван удаа л угаагаарай, дараа нь амт нь зөв гарна. Бүгд кимжангаа амжилттай өнгөрүүлээрэй 🍂', now() - interval '2219 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900196, 900022, '00000000-0000-4000-9000-000000000026', 3, 'Congrats bes, nakaraos ka na sa first kimjang mo! 🎉 Ganyan talaga — hindi ka gragraduhan ng mga ajumma, iko-correct ka lang tapos tuloy ulit, tapos ''kimchi ate'' ka na rin sa grupo 😄 Trick sa gochugaru na naiwan sa kamay: mag-scrub muna ng konting cooking oil bago mag-sabon, mawawala agad ''yan (ito ang turo ng kapwa ko Filipino sa dorm). At tama ang leave-it-out-for-a-day-then-fridge — ngayong linggong ''to, best friend mo na ang kimchi bucket mo. Sana all umuwi ng buong tong, ako buong bucket lang noong isang linggo 🥬😂', now() - interval '2134 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900197, 900022, '00000000-0000-4000-9000-000000000023', 0, 'Saya setuju dengan teman di atas, pindahkan rapat ke siang, itu paling aman 😄 Dari pengalaman enam tahun sini, setiap hari suneung jalan dekat sekolah ditutup mulai pagi, bus memutar, dan taksi di dekat lokasi ujian hampir mustahil dapat. Kalau memang harus pagi, sarapan dulu di kafe dekat kantor klien sambil tunggu jam 10, jalan terasa santai. Jumat pagi biasanya sudah kembali normal, tinggal bagikan sisa Pepero-nya saja.', now() - interval '2117 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900198, 900018, '00000000-0000-4000-9000-000000000041', 10, 'Copying this into my notes for tomorrow''s team kimjang — 2.5kg coarse salt per 10 heads matches what I collected, plus two details from the local ajummas: cut a shallow cross into the bottom stem so salt draws in from the base, and a thick stem that bends without snapping means salting is done. Rinse three times after, not two, or the final kimchi lands over-salted. On 염도: nobody grades you on the meter, the elders just taste the brine and adjust, so a cheap one is optional but nice for a first-timer who wants numbers.', now() - interval '2065 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900199, 900022, '00000000-0000-4000-9000-000000000022', 4, 'पहिलो किम्जाङ जितेमा बधाई। हातको गोचुगारुको गन्ध जान्छ भनेर मालिक्नीले सिकाउनुभएको थियो: हातमा खाना पकाउने तेल (식용유) लगाएर मालिस्नुहोस्, अनि भाँडा माझ्ने साबुन (주방세제) ले धुनुहोस्, मैले त्यसै गरेर रातभर पोलिनबाट बचेँ। डल्लो भने एक दिन कोठाको तापमा राखेर फ्रिजमा हाल्नुहोस्, त्यही तरिका मीठो हुन्छ।', now() - interval '2053 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900200, 900009, '00000000-0000-4000-9000-000000000039', 1, '크런치가 겨우 정리돼서 다행이에요! 우리 사무실도 11/11에 사무실용 페페로를 나눠 먹었는데, 간식 시간에 다 같이 웃던 게 요즘 제일 좋은 기억이에요 🍫 회식을 배포 후 일주일 뒤로 미루신 판단이 진짜 지혜로운 것 같아요, 저희 팀도 연말회식 장소를 막 예약했는데 상차림이 또 날것 위주가 아니기를 조마조마 바라는 중이에요. 참고로 성수 크리스마스 팝업은 인기 있는 곳은 사전 예약제인 경우가 있으니 가기 전에 꼭 확인해 보세요. 수능도 내일이니, 이번 주만 조금만 힘내요!', now() - interval '2058 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900201, 900024, '00000000-0000-4000-9000-000000000027', 3, 'Sarap, this sounds exactly like my week — I grabbed half-price Pepero boxes right after 11/11 and handed them out in my classes, and the students'' break time turned into a little exchange party too 😄 Your first padded coat will be worth every won, and the bubble wrap + electric blanket on a 30-minute timer before bed combo is exactly what saved me my first winter here, our old ondol would have eaten us alive otherwise. And I feel you about Thursday — I moved all my suneung-day lessons to the afternoon so the roads near the test sites stay quiet for the kids, seeing them head off buried in practice tests gives me goosebumps and makes me want to quietly cheer too. Stay warm, your students are lucky to have you 🍫❄️', now() - interval '1983 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900202, 900021, '00000000-0000-4000-9000-000000000015', 4, 'How sweet is that — learning the salting from the elders in your own building sounds like the absolute best first kimjang, and good for you for signing up! 🥬 Mine with the spouses'' club is this Sunday too and I''m collecting the same kit: cotton gloves under the rubber ones, knee pad, and clothes that go straight in the wash. Don''t worry about your Korean one bit — from everything I''ve read on these kimjang threads, an ajumma will just grab your hands mid-chop and fix them, and smiles plus "네!" carry you a long way. Fixin'' to bring extra Pepero myself since Sunday is right after 11/11, so enjoy every tub of kimchi you earn, y''all! 🍪', now() - interval '1933 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900203, 900018, '00000000-0000-4000-9000-000000000037', 11, '비율 공유 감사해요. 저는 내일 시어머니와 두 번째 김장이라 이 글을 계속 들여다보고 있어요 ㅎㅎ 염도는 물이나 국물에 소금이 얼마나 녹아 있는지를 퍼센트로 나타내는 말인데, 절임할 때는 2~3%, 완성 김치는 1.5~2% 정도라는 위의 설명이 정확합니다. 다만 저희 집에선 시어머니가 간을 입맛으로 잡으셔서 계량기는 늘 장식이더라고요 아이가. 그래도 숫자를 미리 알고 가니 마음이 훨씬 편해요. 절임 배추는 세 번 헹구시고, 완성된 김치는 용기에 날짜를 적어두면 오래된 것부터 먹기 편합니다. 내일 김장 다들 잘 마치시길 응원할게요.', now() - interval '1984 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900204, 900024, '00000000-0000-4000-9000-000000000037', 4, '7년째 살아도 페페로 데이는 여전히 귀엽다고 생각해요. 쉬는 시간 교실이 작은 파티가 된다는 표현이 딱 맞네요. 푹신한 패딩은 잘 고르셨고요, 뽁뽁이와 전기요 타이머 조합은 저희 집에도 효과가 컸습니다. 내일 수능 보는 아이들이 조용히 잘 볼 수 있기를 진심으로 바랄게요.', now() - interval '1945 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900205, 900013, '00000000-0000-4000-9000-000000000002', 12, '보건소 독감주사는 예약 없이 외국인등록증이랑 건강보험증만 들고 가면 되고, 아침 10시 전에 가면 줄이 짧습니다. 저희 주방 직원들도 이번 주에 다 맞고 왔어요, 겨울에 감기 걸리면 납품이 전부 엉망이 됩니다. 난방은 밤새 돌리지 말고 보일러를 예약 모드로 해서 잠들고 한두 시간 뒤에 끊기게 하세요, 전기요는 타이머 30분에 따뜻한 물병 하나면 최소한으로 버팁니다. 마, 난방비는 12월 중순까지가 제일 무섭고 그 다음은 참을 만해집니다 👍', now() - interval '1871 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900206, 900025, '00000000-0000-4000-9000-000000000012', 1, 'อ่านแล้วอดอิจฉาที่ตู้เย็นเต็มด้วยคิมจีมากค่ะ ฉันยังไม่ได้ทำคิมจังเลย กลัวว่าหลังจะตามหลังเตารีดเต็มวันแบบในโพสต์ 555 🥶 ทริคตั้งยันเอ 20 องศาแล้วโหมดเวชุลตอนออกบ้าน ฉันกำลังทำอยู่เหมือนกันค่ะ เพื่อนในกระดานแนะนำมาว่าช่วยกู้บิลธันวาได้เยอะ เดแบคเลย ส่วนวัคซีนหวัดฉันยังกลัวเข็มอยู่ แต่จะรีบไปแต่เช้าก่อนสิบโมงตามที่คุณบอกนะคะ 555 เชียร์น้องสุเนิงวันนี้ให้ทุกคนได้คะแนนดีๆ ด้วยนะคะ 🍁🍫', now() - interval '1873 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900207, 900005, '00000000-0000-4000-9000-000000000042', 18, 'यह रिमाइंडर तो मेरे लिए भी था यार 😅 मैं भी हफ्ते भर पहले गुन बोगनसो में ही फ्लू सुई लगवाई थी, बाजू दो रात दुखी, न — सुई वाली जगह पर तौवल में गरम पानी डालकर सिकाई की, काफी आराम मिलता है। और गुरुवार के सुनूंग की बात सच है — यहाँ देजॉन में भी शहर सुबह 7 बजे से ही धीमा पड़ जाता है। मैंने तो रात को ही बस नोसन लिस्ट देखकर प्लान बना लिया है: सुबह चालीस मिनट पहले निकलूँगी, वरना लैब की मीटिंग उड़ जाएगी। एक सवाल न: कैंपस की तरफ जाने वाली मेरी बस टेस्ट साइट के पास से गुजरती है — देजॉन में किसी को पता है कि सुनूंग दिन कौन कौन सी लाइनें बेवे होती हैं? सुनकर थोड़ी राहत मिलेगी 😊', now() - interval '1837 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900208, 900020, '00000000-0000-4000-9000-000000000036', 5, 'У меня тоже в субботу кимджанг, с компанией, и тоже первый раз — нервничаю за посолку не меньше вас. Из всего, что тут советовали: тонкие хлопковые перчатки под резиновые (холодная солёная капуста руки сводит моментально) и наколенник — уже в рюкзаке. А на 11/11 закупила Пеперо, часть возьму коллегам, так что вашу идею с волонтёрами только одобряю. Удачи нам обоим, потом отчитайтесь!', now() - interval '1759 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900209, 900016, '00000000-0000-4000-9000-000000000038', 7, 'お母様の透析が無事に始まりますように、心から願っています。私の小さな習慣は、地下鉄ではマスク、帰宅したら20秒の手洗い、そして朝の通学では薄いスカーフで鼻と口を覆うことです。冷たい空気を直接吸わないだけで、去年より体の調子が良い気がします。電気毛布は寝る30分前だけつけて、保温ボトルのお茶も欠かせません。どうぞ温かくお過ごしください ❄️', now() - interval '1730 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900210, 900026, '00000000-0000-4000-9000-000000000011', 1, 'เชียร์หลังให้นะคะ หนูทำคิมจังกับพี่อาจุมมาที่ฟาร์มมาสองปีแล้ว ตัวเลขเกลือ 2.5 กิโลต่อกะหล่ำปลี 10 หัวถูกต้องเลย พลิกหลัง 6 ชั่วโมงพอดี 🔥 เพิ่มนิดนึง: ใส่ถุงมือผ้าบางๆ ข้างในก่อนใส่ถุงยางยาว เกลือเย็นทำให้มือชาไวมาก ส่วนคิมจีสำเร็จแล้วให้ตั้งไว้ข้างนอกประมาณหนึ่งวันก่อนเข้าตู้เย็น รสจะเข้าที่กว่า แล้วอย่าลืมถุงใบใหญ่ไปด้วยนะคะ เพราะพี่อาจุมมาชอบยัดคิมจีให้กลับบ้านเสมอ 555 🍂', now() - interval '1626 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900211, 900019, '00000000-0000-4000-9000-000000000044', 5, 'Baker solidarity on that gas bill 😅 ours jumped the same week, and Pepero season made it worse — our éclair rush had the ovens running nonstop on the 11th. The 2+1 deal trick is smart, and enjoy the kimjang: a tub of fresh kimchi is the best November trade 🥐', now() - interval '1513 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900212, 900021, '00000000-0000-4000-9000-000000000029', 5, 'Би өнгөрсөн бямба найзынхаа гэр бүлийн кимжанд орж хоёр дахь удаагаа ажумма нарын давсалалтыг судлаад ирлээ 😊 Апартментийн хувилбарын тухай: манай кимжанд ч гэсэн оролцсоныхон хүн бүр нэг сав кимчи авч гэртээ явдаг байсан. Арван толгой байцанд 2.5 кг том ширхэгт давс хэрэглэдэг гэж надад хэлсэн, зузаан иш нугалахад хагарахгүй байвал давсалалт дууссан гэсэн үг. Резинэн бээлийний доор нимгэн хөвөн бээлий өмсөж, өвдөгний дэвсгэрээ мартаж болохгүй — ээж нарынхаа хамт өнгөрүүлэх өдөр нь бас сайн өдөр болно 🍂', now() - interval '1548 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900213, 900005, '00000000-0000-4000-9000-000000000040', 19, '「大田では수능当日、どの路線が迂回するのか知っている人はいますか」という質問がありましたので、調べた範囲でお答えします。大田では試験場周辺の道路が朝7時頃から昼前まで交通規制になり、バスは迂回運行になりますが、地下鉄1号線は通常どおり運行するので、試験場を避けた駅から乗るのが一番確実だと思います。私のアパート近くのバスも路線が変わるため、当日は普段より40分早く出発する予定です。迂回の案内は市のアプリや停留所の告知に前日夜に出るので、水曜の夜にもう一度確認しておくと安心です。', now() - interval '1448 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900214, 900018, '00000000-0000-4000-9000-000000000042', 12, 'अरे यह अनुपात तो इसी हफ्ते लैब के पहले किमजाङ से बिल्कुल मिलता है यार — अजुम्मा ने वहाँ भी दस बेचू पर लगभग ढाई किलो गोउन सोगुम लगाया था, पत्तों के बीच ज़ोर से ठूंसकर और पाँच-छह घंटे बाद अंडा देकर, आपका हिसाब पक्का है। येमदो वाला जवाब ऊपर सही है: जोरीगी (नमकीन) में दो-तीन प्रतिशत, तैयार किमची में डेढ़-दो — फिर भी आख़िर में अजुम्मा चखकर ही तय करती हैं न, मीटर से ज़ुबान आगे चलती है। मेरी टिप: किमची के हर डल्लो पर नित्जा (तारीख) लिख दो ताकि पुरानी से पुरानी पहले खत्म हो, और धोना तीन बार ही करना — दो बार में नमक बच जाता है 😊', now() - interval '1550 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900215, 900023, '00000000-0000-4000-9000-000000000002', 3, '바스락 소리 난다고 문 열어주지 말고, 환기는 아침 잠깐만! 다행히 저희 가게도 유사시 대피 시설 있다고 합니다 👍 아이들은 김장할 때 자기 손 사이즈 고무장갑 꼭 쥐여주세요, 어른용은 꼭짓점 새서 고추 양념 다 스밉니다. 14바구니면 튼튼한 냉장고 하나는 마련해야겠는데요, 채소는 신문지에 싸서 차가운 현관 쪽에 두면 오래 갑니다. 마, 아이들 손은 꼭 끼워서 다녀야 합니다.', now() - interval '1430 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900216, 900008, '00000000-0000-4000-9000-000000000001', 14, '我周末也和实验室的同学约了第一次泡菜季，正紧张地翻大家的小技巧：橡胶手套里加一双薄棉手套、戴围裙、带护膝，都记下来了。你周六上午打疫苗、周日泡菜的顺序安排得很好，正好让胳膊休息一天。我提前打了疫苗所以没这个顾虑，祝你顺利，回头我也来汇报战果。', now() - interval '1368 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900217, 900012, '00000000-0000-4000-9000-000000000040', 8, '「요즘 금정산이나 케이블카 주변 단풍 상태 보신 분 계시면 알려주세요」の質問に、大田の様子をお伝えします。大田のキャンパスのイチョウ並木は今週末が最後になりそうで、先日の強い風の翌朝には道一面に葉が落ちていました。朝の光の時間帯は風も弱く、黄色が一番きれいに見えるので、日曜の午前中という予定は正しいと思います。研究の合間に、私も日曜の朝にキャンパスの並木を見に行くつもりです。寒波が来る前に、どうかきれいな紅葉を見に行かれますように。', now() - interval '1378 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900218, 900019, '00000000-0000-4000-9000-000000000026', 6, 'Bes, kapit lang sa gas bill — ganyan din dito sa dorm namin, noong first cold snap halos tumaas ng tatlong beses kaya seal mode: bubble wrap sa bintana, rolled towel sa ilalim ng pinto, electric blanket 30 minutes lang bago matulog 😅 Ganyan din ako noong 11/11, Pepero binili ko para sa kapwa ko sa linya, ''yong 2+1 deal talaga sulit. Sa kimjang: may silicone na ba? 😄 Kapag nag-iisalin ka ng repolyo, manipis na cotton gloves muna BAGO ang mahabang rubber gloves kasi namumuo talaga ang kamay sa malamig na asin, tapos huwag kalimutan ang extra large na bag dahil laging may bucket ng kimchi na ibibigay pagkatapos. Kaya mo ''yan bes, kimjang hwaiting! 🥬💪', now() - interval '1021 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900219, 900027, '00000000-0000-4000-9000-000000000023', 1, 'Enam tahun di galangan Okpo, tips yang sama persis: sepatu karet tebal dan thermal dari lapak pasar jauh lebih murah daripada toko barang kerja di pinggir yard 😄 Tambahan kecil, kalau untuk kerja di area produksi tanya dulu banjang apakah sepatu harus standar keselamatan, karena boot karet biasa kadang tidak lolos saat inspeksi di gerbang yard. Untuk thermal saya biasa beli dua set, satu dipakai satu dicuci, biar tidak beli buru-buru lagi pas dingin parah. Trik harga ikan pagi subuh juga benar, di pasar dekat sini sama, harga turun setelah kapal sandar.', now() - interval '975 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900220, 900007, '00000000-0000-4000-9000-000000000032', 8, 'កុំបារម្ភច្រើនពេក ខ្ញុំក៏នឹងធ្វើគីមជាំងជាលើកដំបូងថ្ងៃអាទិត្យនេះជាមួយគ្រួសារចៅហ្វាយផង ចិត្តក៏ភ័យដូចគ្នាដែរ។ តាមមតិដែលគេផ្ដល់ ពាក់ស្រោមដៃក្រណាត់ស្តើងខាងក្រោម រួចស្រោមដៃកៅស៊ូវែងខាងលើ ហើយយកខ្នើយជង្គង់ទៅ ព្រោះលាងស៊ាងលើដីត្រជាក់អស់ពីរបីម៉ោង។ គេនិយាយថាមិនមាននរណាវាយតម្លៃយើងឡើយ ពេលដៃខុស អាជូម៉ានិយាយជួយកែប្រែតែម្ដង។ មតិខាងក្រោមបង្ហាញថាប្រេងចម្អិតមួយបន្តិចលើដៃ រួចលាងដោយសាប៊ូលាងចាន ក្រហោងបន្ទាប់មករលត់ទៅ ខ្ញុំកត់ត្រាទុកហើយ 🙏❄️', now() - interval '1071 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900221, 900002, '00000000-0000-4000-9000-000000000003', 6, '哈哈做市场营销的来交作业：我第一次寒冬面试也是穿羽绒服过去，正装叠平放在托特包里，在公司附近的咖啡馆或地铁站洗手间换装，人人都是这么操作的，没人会觉得奇怪。自我介绍别熬夜改稿，把它压缩成三个核心点——你是谁、一个最有说服力带数字的项目、为什么是这家公司——出门前大声念三遍，比对着屏幕改十遍管用得多，我后来面人也确实最想听具体的成果数字。提前二十分钟到，在大堂坐着深呼吸，比任何鸡汤都稳。Pepero 留着自己吃吧，考完犒劳自己 哈哈 ✊', now() - interval '933 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900222, 900020, '00000000-0000-4000-9000-000000000045', 6, 'We''re kimjang twins this Saturday — mine''s with my co-teacher''s family and I''m equally terrified of being the slowest one next to the ajummas, eh 😅 The Pepero-for-volunteers idea is genius, you''ll be everyone''s favorite within five minutes. One more tip for the pile: bring the biggest bag you own, because they always send you home with more kimchi than you can carry. Fighting to both of us — may our backs and our chopping survive! 🍁', now() - interval '883 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900223, 900020, '00000000-0000-4000-9000-000000000005', 7, '我们周六同一天都是第一次김장！我也按帖子里的建议备好了合手的橡胶手套、护膝和直接进洗衣机的衣服，还准备了薄棉手套——盐腌过的白菜真的冻手。带Pepero给志愿者的主意太棒了，你五分钟内就会成为全场团宠 😊 慢一点没关系，阿姨们会直接帮你摆正手法的。加油，回来记得晒晒你的泡菜战利品 ❄️', now() - interval '752 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900224, 900015, '00000000-0000-4000-9000-000000000042', 15, 'ये ''पैच नोट्स'' पढ़कर लगा यार मेरी ही इस हफ्ते की सूची सामने आ गई 😅 मैं भी इसी हफ्ते बाज़ार से जेओंगियो (전기요, बिजली का कंबल) देखने गई थी — ऑटो-ऑफ़ टाइमर वाली सलाह अपना ली और दुकान पर ही बटन दबाकर चेक किया; एक बात जोड़ दूँ: केसी टैग (KC) भी ज़रूर देखना, वो सुरक्षा के लिए है, दिखावे के लिए नहीं। गुरुवार की सुनूंग वाली बात सच है — मैंने भी रात को ही बस नोसन लिस्ट देखकर प्लान बना लिया; 8:40 पर जब चोंगचवी (청취) टेस्ट के लिए पूरा शहर चुप हो जाता है तो रोंगटे खड़े हो जाते हैं, इसलिए चालीस मिनट पहले निकलूँगी और लैब मीटिंग दोपहर में धकेल दी है। और शनिवार किमजाङ के लिए मुरीकपेड न भूलना न — मेरी कमर इसी हफ्ते पहले वाले किमजाङ से अब तक याद दिला रही है 😅', now() - interval '777 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900225, 900022, '00000000-0000-4000-9000-000000000023', 0, 'Terima kasih atas tips minyak goreng-nya, semalam coba di dorm langsung berhasil, bau gochugaru hilang tanpa mikir lama 😄 Juga catat tentang sarung tangan katun tipis di dalam karet, kalau ikut kimjang lagi tahun depan sudah siap. Satu hal lagi yang saya belajar minggu lalu, pilih tong kimchi berlabel besar, kalau kekecilan sisa kimchi akhirnya dipindah dua kali.', now() - interval '684 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900226, 900019, '00000000-0000-4000-9000-000000000011', 7, 'ซื้อ 2 แถม 1 สำหรับเพื่อนร่วมกะเย็นอันนี้ชอบมากค่ะ แถมปิดส่วนต่างค่าแก๊สด้วย 외출 กับผ้าห่มไฟฟ้า 30 นาที ถือว่าทำดีมากเลย 👍 คิมจังที่ศูนย์วัฒนธรรมหลากหลายสนุกมากนะคะ ถ้าอยู่ใกล้ๆ หนูก็จะไปร่วมด้วย ขอแอดทริคเพิ่มเล็กน้อย ใส่ถุงมือผ้าบางๆ ในถุงยางยาว แล้วไปพร้อมผ้าคลุมเข่า นั่งล้างกะหล่ำปลีนานหลายชั่วโมงเลย ส่วนคิมจีที่พี่อาจุมมาให้กลับมาให้พักไว้ที่อุณหภูมิห้องหนึ่งวันก่อนเข้าตู้เย็นจะอร่อยกว่า เชียร์ด้วยหัวใจสายหวาน 🍓🍂', now() - interval '692 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900227, 900019, '00000000-0000-4000-9000-000000000009', 8, 'Deal 2+1 này hời quá, mình cũng mua Pepero chia cho cả line ca đêm hôm 11/11, ai cũng vui hẳn 🍫 Hóa đơn gas tháng này của mình cũng nhảy vọt, may chỉnh boiler sang chế độ 외출 với chăn điện bật 30 phút rồi tắt nên con số đỡ hơn nhiều. Bạn đi kimjang nhớ mang găng cotton mỏng mặc trong găng cao su dài nha, tay đỡ lạnh hẳn. À cả nhà nhớ tiêm cúm sớm sớm nha, trạm y tế buổi sáng ít người xếp hàng lắm 😊', now() - interval '636 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900228, 900026, '00000000-0000-4000-9000-000000000019', 2, '도시락 챙겨가시는 것 정말 현명해요, 김장 다 끝나고 자리에서 나눠 먹는 시간이 절반이거든요. 물류 일하는 습관이 옮아서 그런지, 김치통 하나하나에 만든 날짜를 적어두는 걸 추천해요. 오래된 것부터 꺼내 먹기도 편하고 이웃에 나눠줄 때도 헷갈리지 않습니다. 무릎패드 꼭 챙기시고, 허리 보호를 위해 중간중간 서서 양념 바르는 역할로 자리를 바꿔보세요. 내일 무사히 마치세요 ^^', now() - interval '674 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900229, 900024, '00000000-0000-4000-9000-000000000004', 5, '저희 아이 반에서도 11/11에 페페로를 나눠 먹고 왔는데, 사다 보니 부족해서 두 박스를 더 사러 갔어요. 그래도 아이가 반 친구들과 나누고 좋아하니 그만한 것 같아요 ㅎㅎ 첫 패딩 잘 고르신 것 같고, 창문에 뽁뽁이 붙이고 전기요는 취침 30분 전에 타이머로 켜는 조합은 저희 집에서도 효과가 확실했어요. 수능 보는 아이들 모습을 보면 저도 마음이 쑥쑥 내려가네요, 모두 좋은 결과 있길 진심으로 응원합니다.', now() - interval '559 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900230, 900028, '00000000-0000-4000-9000-000000000008', 1, '이 글 덕분에 내일 김장이 마음이 놓여요, 저희도 배추 열 포기에 굵은 소금 2.5kg이 시어머니 방식이랑 똑같네요. 갓은 배추보다 소금이 훨씬 덜 들어서 열 포기만 덜어서 절이면 돼요. 완성 김치를 하루 실온에 두고 냉장고에 넣는 것도 맞아요, 작년에도 이틀 쯤 지나니 딱 맛이 들었어요. 줄기가 부러지지 않고 휘어지면 절임이 끝났다는 것도 기억할게요 🙏', now() - interval '528 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900231, 900016, '00000000-0000-4000-9000-000000000031', 8, '같은 몽골 사람으로서 겁나는 마음 너무 잘 알아요 😊 저희 가게도 아침 일찍 열고 준비하느라 차가운 공기 많이 마시는데, 얇은 머플러로 코와 입을 가리고 걸어가니 목이 확 편해졌어요. 그리고 사장실에 따뜻한 우유차(수테이 차이) 보온병을 하나 두고 하루 종일 한 모금씩 마시는데, 비타음료보다 몸이 편해요. 어머니 투석 처음이니 걱정되실 텐데, 병원 다니시는 일이 순조롭게 잘 되길 진심으로 기도할게요 ❤️', now() - interval '363 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900232, 900016, '00000000-0000-4000-9000-000000000005', 9, '愿透析顺利开始，请一定多保重 🌊 我的小习惯和你很像：地铁全程戴口罩、回宿舍第一件事洗手20秒，去海边散步时用薄围巾挡住鼻子——冬天的海风又冷又咸，直接吸进去最容易中招。电热毯睡前定时30分钟就关，暖和又不心疼账单。等你方便的时候跟大家说一声进展哦，我们都惦记着你 ❄️', now() - interval '364 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900233, 900025, '00000000-0000-4000-9000-000000000040', 2, '「독감 주사를 아직 안 받으신 분들은 미리 받아 두시길 권해요」の部分、まさに私宛ての警告でした。実験の関係でずっと先延ばしにしていたのですが、この投稿を読んで土曜の朝、実験前の空いた時間に受けに行くことにしました。暖房については「밖에 나올 때 보일러를 완전히 끄기보다 외출 모드로 두고」のアドバイスに加えて、夜は예약タイマーで起床の1時間前だけ暖房がつく設定にすると、寝ている間のガス代がだいぶ抑えられました。12月の請求書、一緒に乗り切りましょう。', now() - interval '424 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900234, 900022, '00000000-0000-4000-9000-000000000019', 5, '첫 김장 잘 마치셨네요, 양념 바르기 세 시간이면 정말 어른들 스타일로 잘 배우신 거예요. 손의 고춧가루 냄새는 먼저 식용유를 소량 묻혀 문지른 뒤 주방세제로 씻으면 금방 빠져요, 저도 매년 이렇게 합니다. 절임배추를 손으로 만지는 건 절이기가 충분히 됐는지 두꺼운 줄기가 반으로 꺾이지 않고 부드럽게 휘어야 완성이에요, 다음번에 배우시면 그것도 어른들이 알려주실 거예요. 완성 김치는 하루쯤 실온에 둔 후 냉장고에 넣고 통에 날짜를 적어두면 오래된 것부터 먹기 편합니다 ^^', now() - interval '258 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900235, 900014, '00000000-0000-4000-9000-000000000001', 5, '我不是清真的，但可以补充点实用信息：圣水的圣诞快闪店周末中午以后排队非常长，尽量工作日或上午10点前过去；2号线圣水站出来就是，江边风大，记得带暖宝宝。关于看配料表这个提醒很对，节日限定甜品和热饮经常藏明胶和酒精，我上周给实验室同学分Pepero前也挨个看了配料表，原味和巧克力味的基本没问题，带果冻、棉花糖夹心的要留意。祝期末顺利。', now() - interval '302 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900236, 900027, '00000000-0000-4000-9000-000000000011', 2, 'หนูเฮ็ดโรงเรือนสตรอว์เบอร์รีแถวอีชอน กะเช้าตีห้าเย็นจนนิ้วชาเลยค่ะ ❄️ ขอเสริมเรื่องเลเยอร์สำหรับทำงานกลางแจ้งตอนเช้า ใส่เทอร์มอลบางใน ชั้นกลางฟลีซ ทับด้วยแจ็คเก็ตกันลม แล้วยัดแพ็คอุ่น (핫팩) ของไดโซ่ไว้ในถุงเท้าก่อนใส่บูท อุ่นขึ้นเยอะจริงๆ ส่วนมือใส่ถุงผ้าบางใต้ถุงยางหนา เหมือนตอนทำคิมจังเลย ไม่มือเปื่อยจากน้ำเย็น 🍓', now() - interval '212 minutes');
INSERT INTO boundless.comments (id, post_id, user_id, anon_no, body, created_at) VALUES (900237, 900016, '00000000-0000-4000-9000-000000000017', 10, 'Aka, dialysis boshlanishi muvaffaqiyatli o''tsin — oilangizga hamma narsa yengil bo''lsin. Sizning tartibingiz menga to''g''ri ko''rinadi, men ham shunga o''xshash yashayman: avtobusda niqob, yotoqxonaga kirib 20 soniya qo''l yuvish, sovuqda munpungji bilan burun-og''izni yopib yuraman. Gripp emagini shu hafta bogeonso''da oldim — ertalab 10 dan oldin boring, navbat qisqa, qo''l bitta kechagina og''ridi. Elektr ko''rpani uxlashdan 30 daqiqa oldin yoqib o''chiraman, boiler tun bo''yi yoqilmaydi — gaz hisobi shu tufayli omon qoldi. Pepero almashishingizni o''qib xursand bo''ldim, sovuq kunlar iliq kichik narsalar bilan osonlashadi 😊', now() - interval '121 minutes');
